// Englische Prosa-Übersetzungen für die Timeline-Ereignisse (Side-Car).
// Schlüssel = fortlaufender Index (flattened timeline[].events[]). Fallback: Deutsch.
window.timelineDataEn = {
 "0": {
  "title_en": "Birth in St. Gallen",
  "text_en": "Adolf Schlatter, born in St. Gallen\nas the seventh of eight children of the merchant Stephan Schlatter and his wife Wilhelmine Schlatter née\nSteinmann."
 },
 "1": {
  "title_en": "Start of elementary school",
  "text_en": "Attendance at the elementary school in St. Gallen.\nFirst experience of being bound\ninto people and state through the payment of a\ncompulsory contribution towards the purchase of the Rütli by\nthe Swiss Confederation.\n\nReligious formation through regular churchgoing with his mother and Christian family life in the home of his father, who, although a member of a free church,\nwas nonetheless lovingly bound to his wife and\nchildren in faith in Jesus.\n\nEven as a child Adolf Schlatter received\nstrong impressions of nature as God's creation,\non family walks while\ngathering flowers and medicinal herbs (his\nfather was a trained pharmacist) and on extensive hikes in the Swiss mountains."
 },
 "2": {
  "title_en": "Collection of poems in a school exercise book",
  "text_en": "The twelve-year-old copies into a school exercise book\n48 poems by Swiss and German poets: \"Gedichte, gesammelt von\nAdolf Schlatter im Jahre 1864 und 65\"\n(Inventory no. 152)."
 },
 "3": {
  "title_en": "Gymnasium St. Gallen; decision for theology",
  "text_en": "Attendance at the Gymnasium St. Gallen until\nhis school-leaving examination in spring 1871.\n\nHis teacher of Latin and Greek,\nFranz Misteli, advises him to study\nphilology. Adolf decides, however, to become a theologian. His mother plays a\nsignificant part in this decision;\nit is prompted by a conversation with\nhis eldest sister Lydia, a teacher\nin St. Gallen."
 },
 "4": {
  "title_en": "Studies in Basel; formative impressions",
  "text_en": "Studies in philosophy and theology in\nBasel. Member of the student fraternity\n\"Schwizerhüsli\". Significant impressions from\nthe philosopher Karl Steffensen: He made it\nvisible to me that thinking is worship,\nbecause truth is God's gift ...\"\n(Quotation from Schlatter's \"Rückblick\", 1952,\npage 40.)\n\nHis own studies of Semitic languages.\nFirst interest in Christian ethics\nas a listener at the lecture \"Grundriß der Ethik\"\nby J.F. Herbart.\n\nFurther impressions as a listener of Jacob\nBurckhardt and of the lecture on Plato\nby Friedrich Nietzsche.\n\nCritical engagement with Spinoza."
 },
 "5": {
  "title_en": "Matriculation in Tübingen",
  "text_en": "Matriculation in Tübingen.\nAttendance at 15 lectures over 3 semesters,\namong them New Testament Introduction and\nHistory of Dogma with Weizsäcker; Christian ethics, doctrine of faith and New Testament exegesis (Ephesians, Timothy)\nwith J.T. Beck.\n\nStrong impression of the personality and\nteaching of J.T. Beck.\n\nMember of the student fraternity \"Wingolf\", which was affiliated with \"Schwizerhüsli\"."
 },
 "6": {
  "title_en": "Leaving certificate from Tübingen",
  "text_en": "Leaving certificate from Tübingen."
 },
 "7": {
  "title_en": "Further studies in Basel",
  "text_en": "Further studies in Basel, including as a listener\nof Overbeck."
 },
 "8": {
  "title_en": "Theological examination in Basel",
  "text_en": "Sitting of the theological examination at\nthe Protestant Theological Faculty of the\nUniversity of Basel."
 },
 "9": {
  "title_en": "Ordination in St. Gallen",
  "text_en": "Ordination in the church of St. Laurenzen in St. Gallen with a sermon on Mark 1:14 and 15 (Inventory no. 258)."
 },
 "10": {
  "title_en": "Parish administrator in Kilchberg",
  "text_en": "Parish administrator in Kilchberg on Lake Zürich.\n\nProfessor Riggenbach, Basel, offers Schlatter a scholarship for further study up to the licentiate. Schlatter declines."
 },
 "11": {
  "title_en": "Curate deacon in Zürich-Neumünster",
  "text_en": "Curate deacon at the 2nd parish office of Zürich-Neumünster.\n\nFriendship with Edmund Fröhlich (1832 to 1898), pastor at the free preaching station St. Anna in Zürich. He prompts Schlatter to engage with the writings of Franz von Baader and St. Martin."
 },
 "12": {
  "title_en": "Curriculum vitae for registration for church service",
  "text_en": "Schlatter's curriculum vitae on registering for church service, a copy for his father (Inventory no. 151)."
 },
 "13": {
  "title_en": "Farewell to Neumünster",
  "text_en": "Farewell to Neumünster.\n\nThe 2nd parish post, which was threatened with abolition, could be preserved thanks to Schlatter's\nconstructive work and be filled again after his\ndeparture."
 },
 "14": {
  "title_en": "Pastor in Kesswil, Utwil and Dozwil",
  "text_en": "Permanent pastor of the parish of Kesswil with\nUtwil and Dozwil, Canton of Thurgau.\nInaugural sermon on Matthew 13:3:\n\"A sower went out to sow.\""
 },
 "15": {
  "title_en": "Marriage to Susanna Schoop",
  "text_en": "Marriage to Susanna Schoop (\"Sausteet\")\nof Dozwil. Wedding conducted by Edmund Fröhlich\nwith a wedding address on 1 Corinthians 13:8.\n\nBesides preaching, teaching and pastoral care\nSchlatter is open to social questions\nand to more advanced theological studies."
 },
 "16": {
  "title_en": "First publication",
  "text_en": "First publication: Die Christologie\nder Bergpredigt. In no. 13/1879 of the Basel\n\"Kirchenfreund\".\n\nIntensified theological work."
 },
 "17": {
  "title_en": "Visit from Samuel Oettli",
  "text_en": "Visit from Samuel Oettli, by now\nprofessor of Old Testament in Bern.\n\nOn behalf of positively minded circles in the Canton of Bern, especially the Evangelisch-Kirchlicher Verein and the Evangelisch-theologischer (Pfarr-)Verein, Oettli moves his friend to turn to a theological teaching post and to apply for a newly to be founded independent lectureship in New Testament at the University of Bern. The entry is to come about through teaching assignments at the Lerberschule and the Evang. Lehrerseminar Muristalden."
 },
 "18": {
  "title_en": "Request for release from church service",
  "text_en": "Request to the Evang. Kirchenrat of the Canton of Thurgau for release from church service."
 },
 "19": {
  "title_en": "Approval of the request",
  "text_en": "Approval of the request."
 },
 "20": {
  "title_en": "Move to Bern and teaching activities",
  "text_en": "Move of the Schlatter couple to Bern,\nRabbenthal.\nEntry into the Freies Gymnasium (Lerberschule) Bern as a teacher of religion and\nHebrew in the two upper classes.\n\nTeaching assignment for religion at the Evang. Lehrerseminar on the Muristalden near Bern."
 },
 "21": {
  "title_en": "Start of the dissertation work",
  "text_en": "Schlatter writes his dissertation\non Johannes der Täufer."
 },
 "22": {
  "title_en": "Request for licentiate examination and habilitation",
  "text_en": "Session of the Protestant Theological Faculty of\nBern: Schlatter's request, 'to sit the licentiate examination before this\nfaculty for the purpose of\nsubsequent habilitation at this\nuniversity.'"
 },
 "23": {
  "title_en": "Submission of the dissertation",
  "text_en": "Submission of the dissertation on\nthe subject 'Johannes der Täufer'. Manuscript\nInventory no. 171."
 },
 "24": {
  "title_en": "Death of his father Stephan Schlatter",
  "text_en": "Death of his father Stephan Schlatter in\nSt. Gallen."
 },
 "25": {
  "title_en": "Licentiate examination magna cum laude",
  "text_en": "Schlatter passes the licentiate examination magna cum laude, for which he has\nto submit written works in 7 subjects\nand is examined orally in 5 subjects.\nHis principal opponent,\nProfessor Nippold, gives him summa\ncum laude in both church history and history of dogma.\n(Faculty minutes of 18\nand 22 December 1880, Inventory no. 848)."
 },
 "26": {
  "title_en": "Venia docendi conferred",
  "text_en": "Upon the faculty's application of 22 December\n1880 for \"approval of his habilitation\",\nthe Education Directorate of the Canton of Bern confers on Adolf Schlatter the venia\ndocendi in New Testament exegesis and\nhistory of dogma."
 },
 "27": {
  "title_en": "Faculty commissions Schlatter",
  "text_en": "The faculty commissions the private lecturer Schlatter to hold a conversatorium on the history of dogma\nas well as, in place of the ailing Professor Oettli, a four-hour\nlecture on Genesis."
 },
 "28": {
  "title_en": "Assignment for the summer semester of 1881",
  "text_en": "The same assignment for the summer semester of\n1881."
 },
 "29": {
  "title_en": "Lectures and exercises from the winter semester of 1881/1882",
  "text_en": "From the winter semester of 1881/1882 Schlatter mainly holds\nNew Testament and history-of-dogma lectures and exercises.\nInventory no. 805; also 732"
 },
 "30": {
  "title_en": "Dora Schlatter leaves her teaching post",
  "text_en": "Dora Schlatter, Adolf's sister,\nleaves her teaching post at the Neue\nMädchenschule Bern to care for her\nmother."
 },
 "31": {
  "title_en": "Monograph submitted to the Hague Society",
  "text_en": "Schlatter submits to the Hague Society\nfor the Defence of the Christian Religion, for the prize it had announced, a monograph \"Glaube und\nGlauben in den Schriften des Neuen\nTestaments\". Manuscript: Inventory\nno. 174"
 },
 "32": {
  "title_en": "Private lecturer's stipend granted",
  "text_en": "Upon Schlatter's application and the recommendation\nof the faculty, the Education Directorate of Bern grants him the private lecturer's stipend of\nSfr. 580.— provided for in the university law,\nnot without a critical reference to his position \"as a special\nrepresentative of orthodoxy and of the\nEvangelisch-kirchlicher Verein\", yet\n\"in consideration of the success of his\nteaching activity and for reasons of fairness towards the\ntheological orientation he represents.\n\nUntil now Schlatter had earned his\nliving from the lecture fees of his\nlisteners (which had grown from thirteen to thirty-five), his work at the Lehrerschule and the Lehrerseminar as well as an\nannual collection of the Evangelisch-kirchlicher Verein.\n\nWith the granting of the lecturer's salary Schlatter obtains (only now) seat and vote in the faculty."
 },
 "33": {
  "title_en": "Prize of the Hague Society",
  "text_en": "Decision of the Hague Society to\naward Schlatter the announced prize\nof 400 guilders for his treatise\n\"Glaube und Glauben in den Schriften\ndes Neuen Testaments\",\nwith the condition of partly reworking it in accordance with the\nremarks made in the \"Programma voor het jaar 1883\"."
 },
 "34": {
  "title_en": "Zwingli celebration in Bern",
  "text_en": "Zwingli celebration in Bern. Probably the lecture \"Zum Gedächtnistag Zwinglis\" here.\nInventory no. 256"
 },
 "35": {
  "title_en": "Stöcker's visit; continued work on treatise",
  "text_en": "Visit from court preacher Stöcker at the Lehrerseminar Muristalden.\n\nContinued work on the treatise on\nfaith."
 },
 "36": {
  "title_en": "Der Glaube im Neuen Testament appears",
  "text_en": "In considerably expanded form there appears:\n\"Der Glaube im Neuen Testament. Gekrönte\nPreisschrift von A. Schlatter, Lic.theol.\nDozent in Bern.\"\nWith \"Programma voor het jaar 1883 und\n1884\".\nE.J. Brill, Leiden 1885.\n\nOn this see further 1927.\nProfessor D. Karl von Weiß comes to Bern to explore the possibility of a call for Schlatter to Halle. An appointment does not come about.\nIn the same year the Calwer Bibellexikon appears with 43 articles by Schlatter. He receives from the Calwer Verlag the commission to write the \"Einleitung zur Bibel\".\nBirth of the first child, Theodor Adolf."
 },
 "37": {
  "title_en": "Lectures on the Epistle to the Romans (Bern)",
  "text_en": "Lectures to men on the Epistle to the Romans in the hall of the Neue Mädchenschule Bern."
 },
 "38": {
  "title_en": "Lectures on the Epistle to the Hebrews; publications on the Epistle to the Romans",
  "text_en": "Continuation of the lectures for men, now on the Epistle to the Hebrews.\nVarious smaller publications on the Epistle to the Romans."
 },
 "39": {
  "title_en": "Publication of \"Der Römerbrief\" and birth of daughter Hedwig",
  "text_en": "\"Der Römerbrief. Ein Hilfsbüchlein für Bibelleser.\" Published by the Calwer Verlag as part 1 of the \"Erläuterungen zum Neuen Testament\".\nThis work, together with the Epistle to the Hebrews appearing in 1888, forms the beginning of the long series of the \"Erläuterungen\".\nBirth of the second child, Hedwig."
 },
 "40": {
  "title_en": "Application for promotion to associate professor in Bern",
  "text_en": "Application of the Protestant Theological\nFaculty to the Education Directorate of\nBern, \"to promote the private lecturer\nLic. theol Adolf Schlatter to\nassociate professor at this\nfaculty.\""
 },
 "41": {
  "title_en": "Renewed application for promotion on account of a call to Kiel",
  "text_en": "Renewed application of the faculty for\nthe immediate promotion of Schlatter\n\"to associate professor of\nNew Testament and dogmatics\", since\nhe had received a call as associate professor\nto Kiel."
 },
 "42": {
  "title_en": "Appointment as associate professor",
  "text_en": "Appointment of Schlatter as associate professor \"of New Testament and systematic theology\".\nThis designation is made at his\nexplicit request."
 },
 "43": {
  "title_en": "Appointment to Greifswald as full professor",
  "text_en": "Appointment by the Prussian government\nas full professor of New Testament exegesis in Greifswald."
 },
 "44": {
  "title_en": "Commission by Wilhelm II; birth of the third child, Paul",
  "text_en": "Document of the commission by Wilhelm II, King of Prussia; linked to this, a professor's salary brought forward by several months.\n\nBirth of the third child, Paul."
 },
 "45": {
  "title_en": "Discharge by the Erziehungsdirektion Bern",
  "text_en": "The Erziehungsdirektion Bern grants,\nin response to his petition of 6 July 1888,\nhis discharge \"with full honours\".\n\nFor Schlatter's petitions and the decrees of the Erziehungsdirektion of the Canton of Bern, see\nthe dossier of the Staatsarchiv Bern on\n\"Schlatter, Adolf. Neutestamentliche und\nsystematische Theologie 1880-1888\"\nInventory no. 838"
 },
 "46": {
  "title_en": "Petition of the Predigerverein Bern regarding the filling of the post",
  "text_en": "Petition of the Evang.-theologischer Predigerverein des Kantons Bern to the Erziehungsdirektion, asking that the vacant post be \"once again filled with a man of positive orientation\", e.g. Lic. theol. Friedrich Barth of Basel."
 },
 "47": {
  "title_en": "Beginning of the Greifswald lectures",
  "text_en": "In Greifswald, Schlatter begins with lectures on Matthäus, the Hebräerbrief and a comparative presentation of synoptic and Johannine Christology.\nIn the lectures of his new Greifswald semesters there are also 8 to 14 Swiss students."
 },
 "48": {
  "title_en": "Application for the award of the Dr. h.c. rejected",
  "text_en": "The application put forward by Professor Oettli at the written request of Professor H. Cremer in Greifswald, to confer on Adolf Schlatter the doctoral degree honoris causa in accordance with academic custom, is rejected by a majority on the grounds that this would create the impression that the faculty was at one with Schlatter's theological orientation, which, however, was predominantly not the case.\n\nSee extracts from the faculty minutes 1888, Inventory no. 850, 851\n\nFor earlier proceedings see extracts from the faculty minutes 1880-1883, Inventory no. 848, 849"
 },
 "49": {
  "title_en": "Publication of \"Einleitung in die Bibel\" and its reception",
  "text_en": "Adolf Schlatter, \"Einleitung in die Bibel\". Calwer Verlag 1889.\n\nThe book, completely finished between August and October 1888, meets with a great response and is later translated into Swedish (1899) and French (1903).\n\nFriendship and working relationship with the Lutheran Hermann Cremer. Schlatter soon comes to be regarded as one of the leading representatives of positive theology in Germany."
 },
 "50": {
  "title_en": "Opposition to Schlatter's understanding of Scripture; visit to Bern",
  "text_en": "The opposition of the circle of friends around Lerber to the understanding of Scripture in his Einleitung in die Bibel prompts Schlatter to attend a gathering at the Bern parsonage of Arnold Bovet, with a lecture and discussion on the doctrine of Holy Scripture."
 },
 "51": {
  "title_en": "Lecture in Berlin; declining of appointments; focus on Jewish contemporary history; birth of Dora",
  "text_en": "Lecture on \"Die Kirche und die negative Kritik\" at the Berlin Pastoral Conference chaired by Adolf Stöcker.\n\nSchlatter declines an appointment to Bonn, as he had earlier declined appointments to Basel, Heidelberg and Marburg.\n\nHis exegetical work on the New Testament leads Schlatter increasingly to occupy himself with Jewish contemporary history, especially with Josephus.\n\nBirth of the fourth child, Dora."
 },
 "52": {
  "title_en": "Journey to Palestine with Samuel Oettli",
  "text_en": "Together with Samuel Oettli and three other friends, Schlatter travels through Palestine, that is, \"the land west of the Jordan from Hebron to Beirut\" (quotation from \"Beiträge\", Heft 1/1920). The outward journey goes via Rome, Naples and Cairo, the return journey via Ephesus and Athens. Diaries, correspondence with the family and the remains of a herbarium testify to Schlatter's extensive studies on this journey.\nInventory no. 166\n\nThrough the mediation of Ministerialrat Althoff he receives for this a substantial grant from the Ministry of Education in Berlin."
 },
 "53": {
  "title_en": "Summer semester 1892: teaching and birth of Ruth",
  "text_en": "Schlatter lectures for the first time on Dogmatik I, and in the following winter semester on Dogmatik II as well as on the history of Israel from Herod to Hadrian.\nBirth of the fifth child, Ruth."
 },
 "54": {
  "title_en": "Counter-statement to Harnack's writing",
  "text_en": "The writing \"Das apostolische Glaubensbekenntnis\" by Adolf von Harnack prompts the board of the Freunde der\nPositiven Union (among them: Adolf Stöcker)\nBerlin to issue a counter-statement."
 },
 "55": {
  "title_en": "Lecture on the Palestine journey in Greifswald",
  "text_en": "Schlatter reports on his Palestine journey to the Greifswalder Geographische Gesellschaft."
 },
 "56": {
  "title_en": "Kreuzzeitung note on the professorship and the Harnack affair",
  "text_en": "Note in the Kreuzzeitung Berlin, according to which Martin Kähler, Halle, but also other names, are under discussion for the new professorship in the local theological faculty; this is being brought into connection with the \"Harnack affair\". (Reinhold Seeberg and Hermann Cremer were meant.)"
 },
 "57": {
  "title_en": "Meeting in Berlin declined",
  "text_en": "When Hermann Cremer hesitates, the\ncommissioner of the Ministry of Education,\nMinisterialrat Althoff, invites Adolf Schlatter\nto a meeting in Berlin. Schlatter\ndeclines to let himself be appointed in\nCremer's place to the University of Berlin."
 },
 "58": {
  "title_en": "Agreement to Althoff and publication of the Palestine book",
  "text_en": "After Cremer's final refusal, Althoff visits Schlatter in Greifswald\nand wrings his agreement from him.\n\nSchlatter remains in Greifswald for the summer semester 1893\nand publishes the book he had begun\nafter the Palestine journey: \"Die Topographie und Geschichte\nPalästinas.\" Calwer Verlag 1893.\n\nThe work is \"dedicated to the theological faculty\nof Halle as a token of gratitude for\nthe doctorate granted to the author\"."
 },
 "59": {
  "title_en": "Decree on the transfer to the University of Berlin",
  "text_en": "Decree of the Ministry of Education Berlin\n\"To the royal full professor\nthe Reverend D. Adolf Schlatter at\nGreifswald\" concerning his transfer \"from\n1 October of this year into the theological faculty of the Königliche Friedrich-Wilhelms-Universität zu Berlin ... with the\nteaching assignment for systematic theology\nand, so far as you feel the need for it, also\nfor the New Testament disciplines.\""
 },
 "60": {
  "title_en": "Inaugural lecture",
  "text_en": "Inaugural lecture in the afternoon, 4 o'clock.\n\"The auditorium, which holds about 110 seats, did not offer sufficient room for the\nlisteners. ... Professor D. Schlatter\n... did not, as expected, give an introductory address, but proceeded at once\nto the subject of his lecture,\nNew Testament theology. He\ndid not read, but spoke freely and vividly.\" (Kreuzzeitung of 24.10.1893) Inventory no. 811"
 },
 "61": {
  "title_en": "Beginning of his teaching",
  "text_en": "Schlatter begins his teaching with\nlectures on Matthäus and New Testament theology as well as a seminar on\ndogmatics."
 },
 "62": {
  "title_en": "Christliche Ethik; relationship with Harnack",
  "text_en": "Schlatter lectures for the first time on \"Christliche\nEthik\".\nAdolf von Harnack distances himself from\nProfessor Schürer's disparagement of the \"Topographie\". From this a\nfriendly relationship develops, while\nthe attitude of the other colleagues towards Schlatter remains cool."
 },
 "63": {
  "title_en": "Tribute by Adolf Stöcker",
  "text_en": "In his Deutsche Evangelische Kirchenzeitung, Adolf Stöcker pays tribute to Schlatter's\nlecture on \"Die Sünde wider den\nHeiligen Geist\" before the Berlin Pastoral Conference on 24 May 1894. Inventory no. 809\n\nDeath of Wilhelmine Schlatter, née Steinmann. Schlatter was closely bound to his mother. Until the very end he wrote her regular letters with reports about his work. Inventory no. 450 ff."
 },
 "64": {
  "title_en": "Teaching in the winter semester 1894/1895",
  "text_en": "Since the winter semester 1894/1895 Schlatter has lectured in regular alternation on dogmatics and ethics, together with New Testament writings likewise in close succession."
 },
 "65": {
  "title_en": "Lecture at the Domkandidatenstift Berlin",
  "text_en": "Lecture by Schlatter at the Domkandidatenstift Berlin on \"Studium und Sexualität\". Transcript by Gustav von Bodelschwingh. Inventory no. 682\nAccording to a written remark to Vater Bodelschwingh of 4 November 1897, Schlatter would have remained in Berlin if he could have become director of the Domkandidatenstift. Inventory no. 902"
 },
 "66": {
  "title_en": "Board memberships in Berlin",
  "text_en": "Schlatter becomes a board member of the Evangelischer Verein für kirchliche Zwecke in Berlin, chaired by Dombaumeister Schwartzkopff.\nHe also becomes a board member of the Berliner Ostafrikamission, later the Bethel-Mission. Connected with this is his friendship and soon further-reaching working partnership with Friedrich von Bodelschwingh."
 },
 "67": {
  "title_en": "Warning against a planned free theological faculty",
  "text_en": "Barkhausen, president of the Evangelischer Oberkirchenrat Berlin, warns Bodelschwingh in a curt letter against the intended \"formation of a free theological faculty\" and rejects his assertion that the regional church's candidate seminaries \"do not fulfil their purpose, that they are purely academic and that Ritschlianism ... prevails in them\".\n\nSchlatter had already been consulted in 1894 on Bodelschwingh's plan for the formation of a theological school in Bethel. Inventory no. 696. Owing to the resistance of the Evangelischer Oberkirchenrat, the plan could only be realised later (1905). Today: Kirchliche Hochschule Bethel."
 },
 "68": {
  "title_en": "Participation in the regional church assembly of the Positive Union",
  "text_en": "Schlatter's participation in the Landeskirchliche Versammlung der Freunde der Positiven Union. This calls for \"the right of the church to exercise a more effective influence on the appointment of theological professors.\" With this the assembly turns against the disadvantaging of positive theology at many theological faculties as a result of the appointment policy of the Prussian Ministry of Education.\n\nSchlatter feels obliged to justify his participation: \"Warum ich an der landeskirchlichen Versammlung teilnahm.\" Article in the Deutsche Evangelische Kirchenzeitung 9/1895. Inventory no. 312, 133."
 },
 "69": {
  "title_en": "Involvement in the Berlin student association and the CVJM",
  "text_en": "During his time in Berlin, Schlatter also serves the Christliche Studentenvereinigung, not without disputes with its pious chairman Graf Pückler, as well as the Christlicher Verein Junger Männer, whose chairman Baron von Rothkirch asks him as late as the winter semester 1897/1898 to lead Bible discussions.\n\nIn the student evenings of the CVJM he held, among other things, Bible studies on the Markusevangelium."
 },
 "70": {
  "title_en": "Eisenach conference and founding of a theological organ; new edition in Calwer Verlag",
  "text_en": "At the Eisenach conference, Schlatter, together with Reinhold Seeberg, Erlangen, is asked by Greifswald colleagues to found a literary organ for ongoing publications of a positive orientation. He likes the plan. He passes over Seeberg, however, and asks Hermann Cremer to jointly edit the organ, for which he proposes the title \"Beiträge zur Förderung christlicher Theologie\". Cremer agrees.\n\nIn Calwer Verlag \"Der Glaube im Neuen Testament\" appears in a 2nd revised edition."
 },
 "71": {
  "title_en": "Beginning of the new series: \"Der Dienst des Christen in der älteren Dogmatik\"",
  "text_en": "In the winter of 1896/1897 Schlatter writes the first work of the new series, which will continue beyond his death, \"Der Dienst des Christen in der älteren Dogmatik.\" Heft 1/1897 of the \"Beiträge zur Förderung christlicher Theologie\". Verlag C. Bertelsmann Gütersloh."
 },
 "72": {
  "title_en": "Commemorative medal awarded",
  "text_en": "Minister of Education Bosse awards\npro-dean Schlatter the commemorative medal for the 100th birthday of Kaiser\nWilhelm I."
 },
 "73": {
  "title_en": "Tübingen faculty proposes Schlatter",
  "text_en": "The Tübinger Evang.-Theologische Fakultät\nresolves to propose \"Professor Schlatter in\nBerlin\" in first place for the 6th professorship, newly established for the New Testament disciplines."
 },
 "74": {
  "title_en": "Stay in Braunlage/Harz; plans for Theological Weeks",
  "text_en": "Schlatter is a guest in the holiday lodgings of Vater\nBodelschwingh in Braunlage/Harz. Here the friendship of the two deepens, and\nthe plan matures to hold regular Theological\nWeeks in Bethel. Theology at\nthe site of the Diakonie - this kindles his enthusiasm.\n\nA similar motive also leads him not to break off the\n- essentially looser - connection with the\necclesiastically and politically controversial Adolf Stöcker. He\nvalues him not so much as the former court preacher, who had already fallen\ninto the Kaiser's disfavour in 1890, nor so much as the\nrousing tribune of the people, but as the\ntireless director of the Berlin Stadtmission. A Christian-social movement that\nproves itself in service to the people\nlikewise remains for Adolf Schlatter an\nessential motive of his thinking and\nacting."
 },
 "75": {
  "title_en": "Teaching in the winter semester 1897/1898 in Berlin",
  "text_en": "In his last Berlin semester Schlatter lectures on the Matthäusevangelium and Dogmatik I. He also continues his work in the Evangelischer Verein für kirchliche Zwecke and in the CVJM Berlin."
 },
 "76": {
  "title_en": "Acceptance of the appointment",
  "text_en": "After repeated correspondence to clarify more precisely his future teaching assignment (New Testament, additionally\nsystematic theology, no practical\ntheology), Schlatter finally writes\nto the dean of the Evang.-Theologische Fakultät\nTübingen: \"Today I wrote to the Minister\nthat I accept the appointment.\""
 },
 "77": {
  "title_en": "Lecture-hall schedule with provisional entries",
  "text_en": "In the lecture-hall schedule of the Evangelisches Stift Tübingen,\nin which the lectures of the Evang.-Theologische Fakultät take place, provisional entries \"Professor Schlatter\" are found\nalready for the summer semester 1897. Inventory no. 837"
 },
 "78": {
  "title_en": "Appointment to Tübingen by the ministry",
  "text_en": "The Kirchen- und Schulministerium Stuttgart\nappoints Schlatter, with effect from 1 April\n1898, to Tübingen to the \"newly established\nfull professorship for the New Testament disciplines\". In this he is left free \"in consultation with the faculty,\nunder certain circumstances also to lecture on dogmatics\nand, as far as possible, to take part in the practical\ninstruction of the students\". Inventory no. 828"
 },
 "79": {
  "title_en": "Newspaper report on the filling of the professorship",
  "text_en": "Report in the Kreuz-Zeitung on disputes over the filling\nof Schlatter's professorship, which is becoming vacant,\nsince Hermann Cremer wishes to remain in Greifswald."
 },
 "80": {
  "title_en": "Communication from the Ministry of Education",
  "text_en": "The Ministry of Education informs the\nEvangelischer Oberkirchenrat Berlin of its intention\nto appoint Professor D. Seeberg to the\nfull professorship for systematic theology that is coming vacant.\nInventory no. 814"
 },
 "81": {
  "title_en": "Beginning of teaching (summer semester)",
  "text_en": "He begins his teaching with\nlectures on the Johannesevangelium\nand Einleitung in das Neue Testament,\nas well as a seminar on pneumatology.\nHe has numerous listeners from northern and\nwestern Germany (among them Friedrich, son\nof Vater Bodelschwingh, his godson).\nThe Stiftler still hold back."
 },
 "82": {
  "title_en": "Entry into the Tübingen faculty",
  "text_en": "Schlatter enters the Evang.-Theologische Fakultät Tübingen."
 },
 "83": {
  "title_en": "Annual assembly of the Evang.-kirchliche Vereinigung (Stuttgart)",
  "text_en": "Schlatter speaks at the annual assembly\nof the Evang.-kirchliche Vereinigung in\nStuttgart on \"Christi Versöhnen und\nChristi Vergeben\".\n\nThe Evang.-kirchliche Vereinigung (Dekan\nChr. Römer), in connection with circles\nof Württemberg Pietism (Stadtpfarrer Friedrich\nJehle), had played a decisive part in his appointment."
 },
 "84": {
  "title_en": "Academic inaugural address",
  "text_en": "Academic inaugural address: Das Neue Testament und die zeitgenössische Theologie\nJerusalems. Manuscript, 20 sheets. Inventory no. 770."
 },
 "85": {
  "title_en": "First Theological Week in Bethel",
  "text_en": "First Theological Week (\"Theologischer Kursus\") in Bethel. Schlatter speaks\non \"Die Wirkung des Heiligen Geistes\nin den Gläubigen\", in which he touches on essential\nquestions of Christian ethics.\nFrom then on, up to and including\n1932, Schlatter takes part with lectures and devotions in almost all of the Theological\nWeeks in Bethel, which mostly took place at\ntwo-year intervals. Complete listing by\nPastor Jaspers. Inventory no. 679"
 },
 "86": {
  "title_en": "First Tübingen Licentiate and further licentiates",
  "text_en": "In view of the cool reserve of the\nSchlatter's first Tübingen licentiate is a\nRepetent: Traub. (This may be Friedrich Traub, the later Ephorus.)\nFurther licentiates follow in the coming\nyears, among them cand. theol. H.A. Hesse\n(magna cum laude).\nCompilation of Schlatter's careful, detailed assessments: Inventory no. 825"
 },
 "87": {
  "title_en": "Obituary for Karl von Weizsäcker",
  "text_en": "As dean of the faculty (1899/1900),\nSchlatter delivers the obituary at the funeral of\nProfessor D. Karl von Weizsäcker."
 },
 "88": {
  "title_en": "Plochingen conference: lecture on the significance of thinking",
  "text_en": "Schlatter's lecture at the Plochingen\nconference on \"Die Bedeutung des Denkens\nfür den Glaubensstand\" is connected with\nthe widely noticed publication\nof:"
 },
 "89": {
  "title_en": "Publication: \"Die Furcht vor dem Denken\"",
  "text_en": "\"Die Furcht vor dem Denken\", issue 4/1900 of the \"Beiträge\" (12 reviews)."
 },
 "90": {
  "title_en": "Appointment proposal for Karl Holl and application for seminar rooms",
  "text_en": "At Schlatter's instigation, the faculty applies to the senate to appoint the Berlin private lecturer Lic. theol. Karl Holl, formerly Repetent at the Tübinger Stift, as associate professor of church and dogmatic history at Tübingen.\n\nIn connection with this, Schlatter submits the application to make available within the university precinct of the Evang.-Theologische Fakultät a few rooms for seminar exercises, since the rooms available in the Evang. Stift were usable for lectures but not for holding seminars.\n\nKarl Holl comes to Tübingen for 6 years and then returns to Berlin as a full professor."
 },
 "91": {
  "title_en": "Address for the Emperor's birthday; book publication",
  "text_en": "For the address on the Emperor's birthday from the University of Tübingen, which this year falls to the Evang.-Theologische Fakultät, Schlatter chooses the theme: \"Was ist heute die religiöse Aufgabe der Universitäten?\"\n\nIn 1901 his \"Geschichte Israels von Alexander dem Großen bis Hadrian\" appears with the Calwer Verlag as the fruit of many years of study. Cf. his lecture of the same name in the winter semester 1899/1900 and similarly already in Greifswald 1892/1893 \"Von Herodes bis Hadrian\".\n\nLater reprint by the Wissenschaftliche Buchgesellschaft in Darmstadt\n1972 with a preliminary note by Professor\nLeonhard Goppelt, Munich, husband of\nSchlatter's granddaughter Dora née\nSchlatter.\n\nA great response in around 30 reviews,\namong them one each in South Africa (Durham)\nand the U.S.A. (Cambridge Mass.)."
 },
 "92": {
  "title_en": "Lecture \"Leben Jesu\" continued",
  "text_en": "With \"Leben Jesu\" Schlatter takes up his\nlectures of 1889 and 1894 (Greifswald)\nand continues them at regular intervals until 1927/1928."
 },
 "93": {
  "title_en": "History of the apostolic church and lecture on Matthew",
  "text_en": "For the first time he lectures on \"Geschichte der\napostolischen Kirche\".\n\nThe regularly recurring lecture on Matthew is this time titled \"Matthäusevangelium mit Berücksichtigung der synoptischen Parallelen\".\n\nIt may be assumed that he otherwise\nalso included Mark and Luke."
 },
 "94": {
  "title_en": "Eisenach fellowship conference: lecture \"Die Gottheit Christi\"",
  "text_en": "At the fellowship conference in Eisenach\n(First Eisenach Conference) Schlatter\nspeaks on \"Die Gottheit Christi\" and\ntakes part in the discussion on\n\"Die Notwendigkeit der Bekenntnung\".\n\nThe occasion for the invitation to give his\nlecture is provided by the issue 5/\n1901 \"Jesu Gottheit und das Kreuz\", published in 1901 in the\n\"Beiträge\".\n\nHermann Cremer, Greifswald, sends him his Wörterbuch der neutestamentlichen Gräcität, published in 1902 by the Verlag Perthes, Gotha, with a handwritten dedication on the title page: \"Adolfo Schlatter Amico dilecto successori felici laborum socio., H. Cr.\""
 },
 "95": {
  "title_en": "Early preacher and Tübingen sermons",
  "text_en": "The teaching assignment of the 6th professorship is connected with the post of a second early preacher at the Tübinger Stiftskirche. Schlatter's eleven sermons in the church year 1902/1903 appear as the 1st volume of his \"Tübinger Predigten\".\n\nIn the following years further volumes appear up to and including 1907/1908, after which further sermon collections appear until 1928."
 },
 "96": {
  "title_en": "Application for an NT church-history seminar",
  "text_en": "On the initiative of the colleagues Schlatter and Karl Müller, the faculty applies to the senate for the establishment of a Neutestamentlich-Kirchengeschichtliches Seminar with a library outside the Evang. Stift in rooms of the university. Presumably general difficulties between Schlatter and the Evang. Stift are becoming apparent here too, as already in the application of 2 February 1900."
 },
 "97": {
  "title_en": "Funeral address for Hermann Cremer; Lütgert co-editor",
  "text_en": "At the coffin of his long-standing friend Hermann Cremer in Greifswald, who died on 4 October 1903, Schlatter speaks on 1 John 5:1 and 11.\n\nIn place of Cremer he wins Wilhelm Lütgert as co-editor of the \"Beiträge\".\n\nExtensive correspondence Schlatter-Lütgert Inventory no. 421, 429, 928"
 },
 "98": {
  "title_en": "Collaboration with the Verein für Innere Mission Tübingen",
  "text_en": "Collaboration with the Evang. Verein für Innere Mission Tübingen, chairman Dekan Elsäßer.\nAssistance in appointing a secretary for the association; in the process contacts with the Süddeutscher evang. Jünglingsbund Stuttgart, Pfarrer Kohler, and the Evang. Gesellschaft Stuttgart, Pfarrer Theophil Wurm."
 },
 "99": {
  "title_en": "Commemorative address on the 100th birthday of J. T. Beck",
  "text_en": "At the faculty's event to mark the 100th birthday of J. T. Beck, Schlatter delivers the commemorative address in the university's auditorium on \"J. T. Becks theologische Arbeit\". Those invited are members of the university, the state and municipal authorities, the Kath.-Theologische Fakultät, the Evang. Konsistorium Stuttgart, the clergy and the officer corps."
 },
 "100": {
  "title_en": "Lecture in Schaffhausen",
  "text_en": "Lecture by Schlatter at the annual meeting of the reformed preachers' society in Schaffhausen on \"Christus und das Christentum, Person und Prinzip\"."
 },
 "101": {
  "title_en": "Preachers' conference Stuttgart: lecture title",
  "text_en": "The title of his lecture \"Die Rechtfertigungslehre in Predigt und Seelsorge\" at the preachers' conference in Stuttgart reveals a concern that was consistently essential for Schlatter."
 },
 "102": {
  "title_en": "YMCA lecture and 3rd revision of \"Der Glaube im Neuen Testament\"",
  "text_en": "A lecture in the Christlicher Verein Junger Männer on the Sea of Galilee at the time of Jesus, commented on the front page of the Tübinger Chronik of 24 February 1905, shows Schlatter's early involvement in the Tübingen YMCA. Inventory no. 853\n\nThe continuing demand for \"Der Glaube im Neuen Testament\" prompts the Calwer Verlag to publish a 3rd revision."
 },
 "103": {
  "title_en": "Lecture \"Der ethische und religiöse Ertrag ...\" (winter semester 1905/1906)",
  "text_en": "With the lecture \"Der ethische und religiöse Ertrag der philosophischen Arbeit seit Cartesius\", Schlatter takes up again the theme of the lecture on \"Die Geschichte der spekulativen Theologie seit Cartesius\" given twenty-four years earlier in Bern. Manuscript of the lecture 1880/1881; Inventory no. 183;"
 },
 "104": {
  "title_en": "Publication of the Cartesius lecture; further editions and response",
  "text_en": "His Cartesius lecture of 1905/1906, with which Schlatter also partly gains recognition among Stift members and Stift Repetents, appears under the title \"Die philosophische Arbeit seit Cartesius nach ihrem ethischen und religiösem Ertrag\" as issue 10/1906 of the 'Beiträge'.\n\nFurther editions in 1910 and 1923 as well as a 4th edition published by Theodor Schlatter with a preface by Helmut Thielicke by the Calwer Verlag in 1959 show a broad response, reflected up to 1924 in 35 reviews and from 1959 in 8 reviews from the fields of\n\ntheology and philosophy (4 reviews). The 1923 edition\nis reprinted with a foreword by Hans\nStroh in 1981 by the Brunnen-Verlag Gießen/\nBasel."
 },
 "105": {
  "title_en": "Lecture: Paulus und das Griechentum (Aarau)",
  "text_en": "The lecture \"Paulus und das Griechentum\"\nat the 10th Schweizerische Christliche\nStudentenkonferenz Aarau marks the start of Schlatter's future (from 1908)\ncollaboration with the Allgemeine Süddeutsche\nChristliche Studentenkonferenzen."
 },
 "106": {
  "title_en": "Lecture \"Jesus und Paulus\" and related talks",
  "text_en": "The theme touches on his lecture\n\"Jesus und Paulus\" of 1906, published by\nTheodor Schlatter in 1940 by Kohlhammer\nStuttgart.\n\nKarl Heinrich Rengstorf considers it important enough to reprint it six decades later. In: Das Paulusbild in der\nneueren Forschung. Wissenschaftliche Buchgemeinschaft Darmstadt, 21969.\n\nA similar direction is also taken by the lecture\n\"Paulus und Timotheus\" at the 1906 annual meeting of the Verein evang. Lehrer in Württemberg, which was grateful for Schlatter's work."
 },
 "107": {
  "title_en": "Lecture in Potsdam: the messiahship of Jesus",
  "text_en": "In connection with the appearance of\n\"Der Zweifel an der Messianität Jesu\" in\nissue 4/1907 of the \"Beiträge\" stands the lecture at the Theologische Konferenz of the\nEisenach fellowship conference in\nPotsdam on \"Die Messianität Jesu in\nihrer geschichtlichen Bedeutung\"."
 },
 "108": {
  "title_en": "Death of Susanna Schlatter",
  "text_en": "Death of his wife Susanna Schlatter.\nSchlatter's obituary for his wife:\nInventory no.: 158\n\nThe loss of his life companion, only\n52 years old, strikes him and also\nthe children hard. His daughters Hedwig\nand Dora henceforth keep house for him and\naccompany him helpfully in\nhis work. With their careful collecting\nand ordering of his manuscripts and his\ncorrespondence, they, together with\ntheir brother Theodor, greatly facilitated the later processing of his extensive estate\nin a Schlatter-Archiv."
 },
 "109": {
  "title_en": "Allgemeine Süddeutsche Christliche Studentenkonferenz in Freudenstadt",
  "text_en": "Allgemeine Süddeutsche Christliche\nStudentenkonferenz in Freudenstadt.\n\nSchlatter speaks on \"Studium und\nGlaube\". The further \"Freudenstädter\nKonferenzen\" and the later \"Tübinger\nPfingstkonferenzen\" with students of all\nfaculties are increasingly shaped by\nthe lectures, morning devotions and\nsummarising closing words held by\nSchlatter.\n\nThe themes of the further lectures are:\nIn Freudenstadt:\n1910: Unsere persönliche Stellung zu\nChristus\n1912: Wir Akademiker und unsere evangelische Kirche\n1914: Unsere Vollkommenheit.\n\nIn Tübingen:\n1917: Der Glaube und die Geschichte\n1920: Das Unser Vater und unsere gegenwärtige Lage.\n\nThe collaboration with the Christian student conferences corresponds to Schlatter's\nintensive ministry to the\nstudent youth in Tübingen, predominantly\nof the Württ. und Deutsche Christliche Studentenvereinigung (DCSV), but\nalso of the Tübinger Bibelkranz (EK).\n\nIn 1907 the Tübingen CSV circle forms a\nhouse commission led by Theodor Schlatter, to which Adolf Schlatter belongs as representative of the Evang.-Theologische Fakultät and the closely associated bursar Hptm.\nKieser as representative of the Stift.\nIn agreement with the house commission, the Württ. Altfreundeverband of the DCSV acquires, with\nthe help of old friend Jakob Ziegler, the\nhouses Österbergstraße 2 and 2 1/2 and\ncreates a provisional home for the\nTübingen CSV circle."
 },
 "110": {
  "title_en": "Theologie des Neuen Testaments (2 volumes)",
  "text_en": "With the Calwer Verlag the \"Theologie\ndes Neuen Testaments\" appears in 2 volumes:\nI Das Wort Jesu - II Die Lehre der Apostel.\n\nThe work is preceded by Schlatter's periodically recurring lectures on Neutestamentliche\nTheologie since Greifswald 1889/\n1890; already in 1881/1882 he held\na seminar in Bern on \"Ausgewählte Abschnitte neutestamentlicher Theologie\".\n\nThe number of reviews (around 45, among them H. Holtzmann, R. Bultmann, R. Knopf and M. Dibelius) surpasses that of all his previous and future publications.\n\nIn the same year Schlatter publishes \"Die Theologie des Neuen Testaments und die Dogmatik\" in issue 4 of the \"Beiträge\".\n\nThe work is included in 1975 in \"Wege der Forschung\", volume 567, Darmstädter Wissenschaftliche Buchgesellschaft. Together with the essay by Trede \"Über Aufgabe und Methode der sogenannten \"neutestamentlichen Theologie\" it appeared in English in 1973 with SCM-Press London."
 },
 "111": {
  "title_en": "Erläuterungen zum Neuen Testament: provisional completion and collected edition",
  "text_en": "Since 1887 Schlatter has been publishing his \"Erläuterungen zum Neuen Testament\" at a slow pace, and since 1904 at a faster pace. This steady work reaches a provisional completion in 1910 with the appearance of the Thessalonian letters, the letters to the Philippians, Peter, Jude and the Revelation of John.\n\nWith volume III of the \"Erläuterungen zum Neuen Testament\", Calwer Verlag 1910, a first collected edition in 3 volumes is available for use \"für den Bibelleser\".\n\nBy contrast, the lectures on the New Testament writings, running through all semesters, show an increasing concentration on the Gospel of Matthew, the Gospel of Luke and the Letter to the Romans; since Tübingen the Corinthian letters also come more into focus. This overall picture predominates throughout my entire lecturing activity."
 },
 "112": {
  "title_en": "Two seminars from the summer semester of 1910",
  "text_en": "From the summer semester of 1910 until the winter semester 1914/1915, Schlatter holds two seminars instead of, as before (and again afterwards), one.\n\nPresumably he now obtained the longed-for seminar rooms in the university in connection with construction work in the Evang. Stift."
 },
 "113": {
  "title_en": "Lectures and \"Das Christliche Dogma\"",
  "text_en": "By intensifying the New Testament seminar work, Schlatter creates a balance for the concentration of his lectures on Matthew, John, Romans and the Corinthian letters; for the first time since Bern and Greifswald he again treats the Letter to the Galatians; up to 1913 there follow the Pastoral Epistles, the Gospel of Luke, the Apocalypse and 1 Peter.\n\nAmong the systematic lectures, the lectures on dogmatics have ranked numerically first since the last Greifswald semesters. From them grows \"Das Christliche Dogma\", Calwer Verlag 1911. The theological-literary resonance, with 18 reviews, falls far short of the response to Schlatter's Neutestamentliche Theologie. His original approach via anthropology, which makes him appear a forward-thinker still relevant today, meets with incomprehension from many.\n\nAlthough Schlatter, with his historical understanding of Scripture, does not tell Pietism what it wants to hear, he is esteemed by it, apart from in Württemberg especially"
 },
 "114": {
  "title_en": "Lecture at the Eisenach fellowship conference",
  "text_en": "also in Westphalia, upon which his regular participation in the Theologische Wochen in Bethel has an effect, and in the Rhineland, where he lectures at the 10th Eisenach fellowship conference in Essen on \"Die kirchliche Gemeinschaft\"."
 },
 "115": {
  "title_en": "Participation in an event on the \"Fall Jatho und Württembergs\"",
  "text_en": "At a lecture by Christoph Schrempf, professor of philosophy at the Technische Hochschule Stuttgart who had been dismissed from pastoral service, on the \"Fall Jatho und Württembergs\" at an event of the Tübingen local group of the Deutscher Bund abstinenter Studenten, Schlatter, alongside the professors Häring, Wurster, Rietschel, Scheel, Traub and Müller, also takes part in the address. Detailed report in the Tübinger Chronik of 22 July 1911; Inventory no. 853"
 },
 "116": {
  "title_en": "Publication of 'Briefe über das Christliche Dogma' and developments in 1912",
  "text_en": "\"Briefe über das Christliche Dogma\", issue 3/1912 of the \"Beiträge\", published, perhaps also because of the not reassuring response to \"Das Christliche Dogma\". The 'Briefe' provoke another 73 reviews. In 1978 they appear, this time with the Calwer Verlag, with a foreword by Hans Stroh, in a 2nd edition.\n\nFor the rest, Schlatter has discontinued his lectures on Dogmatik I and II, which had run continuously until 1910/1911.\n\nIndependently of this, the years since the death of his wife in 1907 until the outbreak of the First World War in 1914 stand out as the peak of his academic effectiveness in the period up to his retirement."
 },
 "117": {
  "title_en": "Attendance figures in the summer semester",
  "text_en": "His attendance figures from 1912 show this, for example: 76 for the four-hour Neutestamentliche Theologie,\n123 for the four-hour Romans lecture, 237 for the five-hour Gospel of Matthew, 141 for the two-hour introduction to theological study; 76\nfor the lower course and 43 for the upper course of the\nNew Testament seminar."
 },
 "118": {
  "title_en": "Lecture and publications",
  "text_en": "An example of his active participation\nin the work of foreign missions is his\nlecture at the Horber Missionskonferenz\non \"Die Gemeinde in der apostolischen\nZeit und im Missionsgebiet\", which in a revised form\nIn issue 6/1912 there follows \"Das Alte Testament\nin der Apokalypse\". Both publications\nprovoke numerous reviews."
 },
 "119": {
  "title_en": "Cross of Honour of the Württemberg Crown",
  "text_en": "On the occasion of his forthcoming 60th birthday,\nthe King confers on him the Cross of Honour of the\nOrden der Württembergischen Krone, combined with personal ennoblement. Adolf von\nSchlatter never claimed his title of nobility."
 },
 "120": {
  "title_en": "YMCA Tübingen: chairman and annual report",
  "text_en": "Elected chairman at the extraordinary members' meeting of the Christlicher Verein Junger\nMänner (CVJM) Tübingen of 20 January 1912\nin place of the resigned Dekan Mäder,\nSchlatter issues the\nannual report 1911/1912 in the monthly bulletin of the Tübingen CVJM."
 },
 "121": {
  "title_en": "Election as substitute member of the regional synod",
  "text_en": "The Evang.-Theologische Fakultät elects Schlatter as substitute for the delegate to the Evang. Landessynode."
 },
 "122": {
  "title_en": "YMCA social evening at the Museum",
  "text_en": "On the occasion of the work of the soldiers' section of the Tübingen CVJM, begun in the winter of 1911/1912, at the association house Hechhalde 2, a social evening takes place at the Museum with the participation of the regimental band, at which Schlatter, as chairman, is able to welcome \"das gesamte Offizierskorps, das Bataillon, viele Veteranen und die beiden Militärgeistlichen\" as well as \"insbesondere die jungen Rekruten an ihrem Ehrentag\". Secretary Eisenmann advocates the establishment of a soldiers' home in Tübingen (Tübinger Chronik of 31.10.1912, Inventory no. 567)."
 },
 "123": {
  "title_en": "Lecture: Mission und Islam",
  "text_en": "In the Akademischer Missions- und Gustav-Adolf-Verein, Schlatter speaks in the small hall of the Museum on \"Mission und Islam\". The lecture appears newly relevant today (Tübinger Chronik of 5.11.1912, Inventory no. 567)."
 },
 "124": {
  "title_en": "1913: monthly bulletin of the Tübingen CVJM",
  "text_en": "From November 1912 until December 1919 Schlatter regularly issues the monthly bulletin of the Tübingen CVJM.\n\nHis service, long practised before and now further intensified, also to the student youth is only one, albeit special, part of his uninterrupted devotion to the laity in church and congregation.\n\nThis also includes many devotions and addresses before women, beginning with the circle of Tübingen domestic helpers led by one of his daughters through to lectures before female teachers. His tireless commitment, with pastoral counselling and biblical instruction, is reflected in countless letters to Schlatter from laypeople of all ages from all over Germany and German-speaking Switzerland."
 },
 "125": {
  "title_en": "Lecture at the Evang. Vereinshaus; article in the Allgemeine Ev.-Luth. Kirchenzeitung",
  "text_en": "In the hall of the Evang. Vereinshaus, Schlatter speaks as part of a lecture series organised by the Deutsch-Evangelischer Frauenbund on 'Erinnerungen an Pastor F. V. Bodelschwingh'.\n\nIn the Allgemeine Evangelisch-Lutherische Kirchenzeitung, D. Wilhelm Laible issues an article series by twelve German theologians on 'Die Wahrheit des apostolischen Glaubensbekenntnisses'.\nAmong them: Adolf Schlatter 'Aufgefahren gen Himmel, wo er sitzet zur Rechten Gottes'. Allgemeine Evangelisch-Lutherische Kirchenzeitung no. 46 (1913).\n\nThe significance of the article is to be understood against the background of the experiences during the Berlin Apostolicum dispute of 1892 and the religious discussion between Christoph Schrempf and the Tübingen theologians in 1911."
 },
 "126": {
  "title_en": "Lecture in the winter semester 1913/1914",
  "text_en": "With his lecture on \"Ausgewählte\nProbleme aus der religiösen Anthropologie\",\nSchlatter takes up the criticism of the approach\nof his Christliches Dogma, in order then\nsubsequently to lecture on its core parts \"Schöpfung\nund Erlösung\" - both an echo of\nhis meanwhile discontinued\ndogmatics lectures."
 },
 "127": {
  "title_en": "Publications and works on ethics and biblical theology",
  "text_en": "Only in Berlin did Schlatter give lectures (3) on ethics. That he nevertheless continued to work intensively on the subject is shown by \"Die Christliche Ethik\". Calwer Verlag 1914. See on this later regarding the 3rd edition of 1929.\n\nSchlatter writes a detailed article for the theological quarterly The Constructive Quarterly, New York, on the relationship of German Protestant theology to the Bible, which appears there in English translation under the title The attitude of German protestant theology to the Bible. Manuscript in German and English: Inventory no.: 817."
 },
 "128": {
  "title_en": "Seminar in the summer semester",
  "text_en": "In the seminar he establishes\nwith \"Probleme aus der Geschichte der neutestamentlichen Ethik\" the connection with\nhis \"Christliche Ethik\"."
 },
 "129": {
  "title_en": "Inauguration of the DCSV-Haus in Tübingen",
  "text_en": "The new DCSV-Haus in Tübingen, built on the plot at Österbergstraße 2 and 2 1/2 with the support of the manufacturer Lechler and substantial loans from Adolf Schlatter, is inaugurated at Whitsun, with, among other things, words of greeting from the Rector of the University, the Tübingen Dean, the chairman of the DCSV, Under-Secretary of State Dr. Georg Michaelis from Berlin, and the Dean of the Protestant Theological Faculty, Professor Schlatter, on 2 Corinthians 3, 17 and 18.\n\nAfter Adolf Schlatter's death, the house, in order to protect it from the grip of National Socialism, is taken over by the Württ. Landeskirche and, at the ceremonial handover by Landesbischof\n\nWurm in November 1938, receives the name \"AdolfSchlatter-Haus der Evangelischen Studentengemeinde\". Its history and\nits incomparably beneficial influence are\npresented in the 1964 commemorative volume\n\"Das Adolf-Schlatter-Haus in Tübingen\"."
 },
 "130": {
  "title_en": "Eulogy at the grave of D. Paul Buder",
  "text_en": "At the grave of Ephorus D. Paul Buder,\nSchlatter delivers the eulogy on behalf of the Protestant Theological Faculty."
 },
 "131": {
  "title_en": "Sermon at the outbreak of war; family events",
  "text_en": "His \"Predigt am Bettag beim\nBeginn des Krieges, Hebräer 4, 16\", published as an offprint by the Verlag der\nEvang. Gesellschaft Stuttgart in 1914, stands under the sign of the outbreak of the First World War.\n\nHis daughter Ruth travels to Edinburgh at the end of July\nto enter the missionary seminary there\nand is surprised there by the outbreak of the war; his son Paul is called up for military"
 },
 "132": {
  "title_en": "War prayer hour in Tübingen",
  "text_en": "service and is wounded. The father\nhastens to the dying man in the field hospital at\nGermersheim and brings his coffin\nto Tübingen. His acceptance of this\nsacrifice, so exceedingly painful to him, is expressed\nin his choice of text for the war prayer hour\nin Tübingen: \"Die mich frühe suchen,\nfinden mich\", Sprüche 8, 17."
 },
 "133": {
  "title_en": "1915: Address, article and lecture series",
  "text_en": "That Schlatter concerned himself early on with the\nquestion of war guilt is shown by his\naddress before the University on the Kaiser's birthday on \"Recht und Schuld in der Geschichte\", published in issue 1/1915\nof the \"Beiträge\".\n\nAlso thematically significant is his\narticle on Biblisches Christentum in\nAllgemeine Evangelisch-Lutherische Kirchenzeitung No. 48 (1915), with the subtitle \"Was\nhaben unsere Theologen für den kommenden\nFrieden zu sagen?\"\n\nIn the hall of the Protestant community house, the Deutsch-Evangelischer Frauenbund organises five\nlectures by Schlatter on the \"Geschichte und\nArbeit des Apostels Paulus\". Among them:"
 },
 "134": {
  "title_en": "Lecture: \"Die Jugend und Bekehrung\"",
  "text_en": "\"Die Jugend und Bekehrung\""
 },
 "135": {
  "title_en": "Lecture: \"Die Anfänge der Mission\"",
  "text_en": "\"Die Anfänge der Mission\""
 },
 "136": {
  "title_en": "1916: Lecture series \"Die Frau in der apostolischen Gemeinde\"",
  "text_en": "In the same setting, Schlatter gives four lectures on \"Die Frau in der apostolischen\nGemeinde\", namely"
 },
 "137": {
  "title_en": "Lecture: \"Die neue Haushaltung\"",
  "text_en": "\"Die neue Haushaltung\""
 },
 "138": {
  "title_en": "Lecture: \"Die neue Ehe\"",
  "text_en": "\"Die neue Ehe\""
 },
 "139": {
  "title_en": "Publication: \"Der neue Anteil an Gott\"",
  "text_en": "\"Der neue Anteil an Gott\""
 },
 "140": {
  "title_en": "Publication: \"Die Mitarbeit für die Kirche\"",
  "text_en": "\"Die Mitarbeit für die Kirche\""
 },
 "141": {
  "title_en": "Correspondence and reactions to a solidarity appeal",
  "text_en": "Jean Massart, Académie royale de Belgique,\ntakes to task the 93 German scholars and\nartists, among them Adolf Schlatter, over\nthe solidarity appeal of September\n1914. Later Dr. Hans Wehberg,\nDeutsche Liga für Völkerbund Berlin, in a\nletter of 14 April 1919 asks that Schlatter\nmight, \"in the interest of resuming\nscholarly relations with\nforeign countries\", together with other scholars issue a declaration that he \"no longer today\nstands on the ground of that appeal\".\n\nTogether with two further foreign letters on this matter from 1916 and 1919: Inventory no. 428/2\n\nAs already in 1914 and 1915, the events of the war are reflected - without, of course, outweighing other themes - in the monthly bulletins of the CVJM\nTübingen edited by Schlatter."
 },
 "142": {
  "title_en": "Lectures in Wiesbaden and contributions in Nachrichten",
  "text_en": "His lectures at the 14th conference of the Eisenacher Bund in Wiesbaden are devoted to the question of the deeper meaning of the war years:\n\"Der lebendige Gott und seine Führung mit\nunserem Volk\"; \"Das Evangelium Jesu Christi\nund unser Volk\".\n\nHis pastoral concern for the soldiers and their relatives speaks from three\ncontributions in the Nachrichten des Württ.\nAltfreundeverbandes der DCSV, issue 12/\n\n\"Das Gebet im Krieg\".\n\"Wir alle mit aufgedecktem Angesicht,\n2. Korinther 3, 18\".\n\"Philipper 1, 6. Abendandacht für Studenten hinter der Front.\"\n\nSchlatter officiates at the marriage of his youngest daughter\nRuth to Pfarrer Friedrich Hinderer,\nHausen bei Brackenheim. The parsonage\nof his son-in-law, especially from 1926\nin Laichingen, is often a refuge for him for work and relaxation."
 },
 "143": {
  "title_en": "1917: Lecture series \"Die Mutter Jesu\"",
  "text_en": "Once again Schlatter gives four lectures organised by the Deutsch-Evangelischer Frauenbund, this time on \"Die Mutter Jesu\", namely"
 },
 "144": {
  "title_en": "Lecture: \"Die Seligkeit der Mutter\"",
  "text_en": "\"Die Seligkeit der Mutter\""
 },
 "145": {
  "title_en": "Lecture: \"Die Beugung der Mutter\"",
  "text_en": "\"Die Beugung der Mutter\""
 },
 "146": {
  "title_en": "Lecture: \"Der Anstoß der Mutter\"",
  "text_en": "\"Der Anstoß der Mutter\""
 },
 "147": {
  "title_en": "Lecture: \"Das Opfer der Mutter\"",
  "text_en": "\"Das Opfer der Mutter\""
 },
 "148": {
  "title_en": "Wilhelmskreuz and publication",
  "text_en": "The King of Württemberg confers on Adolf\nvon Schlatter the Wilhelmskreuz.\n\nThe lecture halls have grown empty, but\nSchlatter takes part in the Theologischer\nKriegshochschulkursus in Lorraine. He publishes the lecture under the title:\n\"Die Gründe der christlichen Gewißheit\",\nCalwer Verlag 1917."
 },
 "149": {
  "title_en": "Lecture at a Christian academics' conference",
  "text_en": "The first Christliche Akademikerkonferenz takes place in the Jugendhaus Eyach bei Geislingen an der Steige, with Schlatter's lecture, likewise shaped by the Reformation year: \"Wie bewahren wir Luther die Treue?\""
 },
 "150": {
  "title_en": "Reformation jubilee: lectures and treatise",
  "text_en": "The 400th year after Luther's posting of the theses also gives his work particular emphasis. At a missionary event he speaks on Luther and\nmission, and his lecture at the\nTheologische Woche Bethel is entitled: \"Das\nWirken des Heiligen Geistes in der Reformation.\"\n\nOf fundamental importance is:\n\"Luthers Deutung des Römerbriefs. Ein\nBeitrag zur vierten Säularfeier der\nReformation\", issue 7/1917 of the \"Beiträge\".\n\nIn this treatise Schlatter concerns himself\nonce more with the doctrine of justification, whose\nLutheran approach appeared altered through the influence\nof Luther, and still more through the radical teaching of Augustine on\noriginal sin adopted by Luther's successors,\nwith the\nconsequence of a devaluation of God's goodness as Creator,\nwhose power remains positively effective even in the fallen\nworld and humanity.\nThis, he holds, led in the churches of the Reformation to\na truncated proclamation of the\nGospel, because it neglected the first articles of faith.\n\nThe later Prelate Ludwig Vöhringer, at that time\ntown pastor in Reutlingen, wins Schlatter\nover to the plan of regular conferences for the\nbody of academics that had grown out of the Freudenstadt and Tübingen student conferences."
 },
 "151": {
  "title_en": "Contribution to the Festschrift for Theodor von Häring",
  "text_en": "To the Festschrift for the 70th birthday of his long-standing friend Theodor von Häring, Schlatter contributes the original piece \"Herz und Gehirn im 1. Jahrhundert\"."
 },
 "152": {
  "title_en": "Lecture on the Weimar circle of poets (Reutlingen)",
  "text_en": "His lecture on the religious significance of the Weimar circle of poets at the Württ. conference of Christian academics in Reutlingen shows the breadth of his thinking."
 },
 "153": {
  "title_en": "Addresses, lectures and contributions",
  "text_en": "His address in Tübingen on the social duty of the educated girl, his lecture on the law and the gospel in preaching to the heathen and in the Christian congregation at the Halle missionary conference, and \"Worte der Besinnung\" in the CVJM monthly bulletin, \"Der Wunsch, das Leben zu genießen\", are small examples of his service in many circles."
 },
 "154": {
  "title_en": "Seminar on Luther's interpretation of Romans",
  "text_en": "From Schlatter's teaching activity, which now moves almost entirely within the field of the New Testament, the seminar on Luther's interpretation of the Epistle to the Romans stands out - probably prompted by the reviews of his treatise \"Luthers Deutung des Römerbriefs\" that had appeared in the meantime."
 },
 "155": {
  "title_en": "1919: Lectures at the Deutsch-Evangelischer Frauenbund",
  "text_en": "Once again Schlatter gives four lectures at the Deutsch-Evangelischer Frauenbund on\n\"Freiheit und Gleichheit in der Gemeinde der Apostel\"\non themes that still appear topical today:"
 },
 "156": {
  "title_en": "Lecture: Die Befreiung vom Geist der Furcht",
  "text_en": "\"Die Befreiung vom Geist der Furcht\""
 },
 "157": {
  "title_en": "Lecture: Die Befreiung vom Druck des Amts",
  "text_en": "\"Die Befreiung vom Druck des Amts\""
 },
 "158": {
  "title_en": "Lecture: Die Gewährung des eigenen Lebens",
  "text_en": "\"Die Gewährung des eigenen Lebens\""
 },
 "159": {
  "title_en": "Lecture: Die Ausgleichung der Unterschiede",
  "text_en": "\"Die Ausgleichung der Unterschiede\"."
 },
 "160": {
  "title_en": "Focus of teaching in the summer semester",
  "text_en": "The focus of his teaching this year lies in a lecture on the Gospel of John and a seminar on the relations of the Gospel of John to the Synoptics."
 },
 "161": {
  "title_en": "Lecture: Die Vergangenheit unserer Kirche",
  "text_en": "\"Die Vergangenheit unserer Kirche\""
 },
 "162": {
  "title_en": "Lecture: Die Zukunft unserer Kirche; notice in the Tübinger Chronik",
  "text_en": "\"Die Zukunft unserer Kirche\".\n\nThe Tübinger Chronik, from whose advertisement section the themes of the lecture series at the Deutsch-Evangelischer Frauenbund of 1915, 1916, 1917 and 1919 are taken, also announces in May 1919\ngatherings of \"Evangelischer Männer\" in the hall of the DCSV, Oesterberg 2\" with lectures and discussion:\n\nThe same notice in the Tübinger Chronik points to a \"Gottesdienst für die männliche Jugend\", Sunday, 4 May, in the Protestant community house with a sermon by Stadtpfarrer Schlatter. Inventory no. 553\n\nProbably around this time Adolf Schlatter handed over his chairmanship of the Tübingen CVJM and the editing of the Monatlicher Anzeiger des CVJM to his son Theodor Schlatter, town pastor in Tübingen."
 },
 "163": {
  "title_en": "Lecture \"Gottes Führung mit unserem Volk\" (Schönblick)",
  "text_en": "An example of Schlatter concerning himself in word and writing with the meaning of the lost war is his lecture on \"Gottes Führung mit unserem Volk\", given at the 3rd conference of Christian academics at the Schönblick."
 },
 "164": {
  "title_en": "Publications and contributions 1920",
  "text_en": "Taking into account the numerous reviews as well as his own lectures on the \"Leben Jesu\", Schlatter issues a revised edition of volume 1 of the Theologie des Neuen Testaments (\"Das Wort Jesu\"). New title: \"Die Geschichte des Christus\", Calwer Verlag, 1st ed. 1920, 2nd ed. 1923; reprint 1977 with a foreword by Hans Stroh and Peter Stuhlmacher.\n\nTheologically and biographically instructive is issue 1/1920 of the \"Beiträge\": \"Die Entstehung der Beiträge zur Förderung christlicher Theologie und ihr Zusammenhang mit meiner theologischen Arbeit, zum Beginn ihres 25. Bandes dargestellt\".\n\nThis treatise partly overlaps with his autobiographical manuscript \"Beim Abschluß der Arbeit. Ein Rückblick\" (Inventory no. 155), on which he worked for years and whose beginnings probably \"reach back before the year 1902\" - so Theodor Schlatter in the foreword as editor of the \"Rückblick\" in 1952 in a special issue of the \"Beiträge\".\n\nIn the New Testament seminar Schlatter has, since as far back as the winter semester 1915/1916, again restricted himself to one class per semester."
 },
 "165": {
  "title_en": "Seminar on the Apocalypse of John",
  "text_en": "For the first time he holds a seminar on the Apocalypse of John."
 },
 "166": {
  "title_en": "South German student conference in Tübingen; Schlatter's lecture",
  "text_en": "The large Süddeutsche Studentenkonferenz in Tübingen, with lectures by Karl Heim, Gerhard Reichel, Adolf Schlatter, Otto Schmitz and Erich Stange, is of importance for the gathering and strengthening of the students who had returned from the war. Schlatter meets the situation in a particularly helpful way with his lecture: \"Das Unser Vater und unsere gegenwärtige Lage.\" The offprint of the lecture from issue 2/1920 of the academic monthly \"Die Furche\" also finds attention in the theological specialist literature."
 },
 "167": {
  "title_en": "First female Licentiate (Lydia Schmid)",
  "text_en": "First female Licentiate with Schlatter as examiner: Lydia Schmid, later religious education teacher at the Katharinenstift Stuttgart.\n\n\"Ich sah im Hörsaal in den Studentinnen eine wenig bedeutende Zugabe.\" Manifold service for circles of women and girls, the influence of his own daughters, and working ties with the Deutsche Christliche Vereinigung Studierender Frauen (DCVSF) changed his attitude: \"Die Folge war, daß ich für alles, was in die weibliche Jugend Bewegung hineinreicht, tief dankbar geworden bin\" (quotations from \"Erlebtes\", Furche-Verlag 5th ed. 1929, page 59)."
 },
 "168": {
  "title_en": "Summer semester: Corpus Johanneum",
  "text_en": "A further focus on the Corpus Johanneum, with a lecture on the Gospel of John and a seminar on questions from the field of Johannine literature."
 },
 "169": {
  "title_en": "New Year article, revised edition of a book, and an honour",
  "text_en": "\"Neujahrswünsche für unser Volk\",\nan article by Schlatter in the Monatsanzeiger des CVJM Tübingen, now edited by\nStadtpfarrer Theodor Schlatter.\n\nRevised edition of volume II of the Theologie\ndes Neuen Testaments:\n\"Die Lehre der Apostel\", Calwer Verlag\n2nd ed. 1922.\nReprinted 1977 with a foreword by Hans Stroh\nand Peter Stuhlmacher.\n\nSchlatter writes his review of Karl\nBarth's Römerbrief in issue 12/1922 of the monthly Die Furche.\n\nThe local branch of the Schwäbischer Albverein\nconfers on \"Prof. Dr. v. Schlatter the badge of honour for 25 years of uninterrupted\nmembership\". It is an eloquent sign of his attachment to nature,\nnot only to the Swabian land but\nalso to the Württ. land that had become his second home. Inventory no. 167/1"
 },
 "170": {
  "title_en": "Teaching in the summer semester",
  "text_en": "In his last semester before his retirement (emeritus status),\nSchlatter lectures on \"Leben Jesu\" as well as\n\"Schöpfung und Erlösung\" and holds a seminar\non problems from the Acts of the Apostles."
 },
 "171": {
  "title_en": "Jäger publishes a series of essays in \"Aufwärts\"",
  "text_en": "The head of the Theologische Schule Bethel, Pastor D. Samuel Jäger, publishes a series of essays on Christian-social questions in \"Aufwärts\"."
 },
 "172": {
  "title_en": "70th birthday – letters of congratulation",
  "text_en": "Honouring letters from the university and the faculty\nand many letters from friends on his 70th birthday."
 },
 "173": {
  "title_en": "Theologische Woche Bethel and Eisenacher Bund",
  "text_en": "At the Theologische Woche in Bethel Schlatter is together with Jäger, as also at the meeting of the Eisenacher Bund in Kassel."
 },
 "174": {
  "title_en": "Release from official duties; early sermon retained",
  "text_en": "The full professor of New Testament disciplines, Dr. Adolf von Schlatter, is released from his official duties. The commission to preach the early sermon on the 4th Sunday of the month remains in force.\n\nHe makes use of his right, as a retired professor, to continue giving lectures:"
 },
 "175": {
  "title_en": "Lectures in the winter semester 1922/1923",
  "text_en": "Lecture on Römerbrief and Neutestamentliche Theologie; seminar once again on the Apokalypse des Johannes."
 },
 "176": {
  "title_en": "Article in \"Die Furche\" on the religious-social movement",
  "text_en": "The Christian-social movement that once originated with Stöcker had always been close to his heart, in principle long before his Berlin years. One sign of this is his article \"Die religiös-soziale Bewegung in der Schweiz\" in issue 12/1922 of the academic monthly \"Die Furche\", Martin Warneck-Verlag Berlin."
 },
 "177": {
  "title_en": "Writes \"Erlebtes\" and works on the Bible lexicon",
  "text_en": "In the somewhat quieter year after his\nretirement Schlatter writes his\n\"Erlebtes\", which will appear in 1924, and\nworks on his many articles\nfor the forthcoming revision of the\nCalwer Bibellexikon.\n\nHis continuous engagement with\nJosephus is evident in issue 1/1923 of the\n\"Beiträge\": \"Der Bericht über das Ende\nJerusalems. Ein Dialog mit Wilhelm Weber.\"\nKarl Heinrich Rengstorf includes the treatise in 1970 in \"Kleinere Schriften zu Flavius\nJosephus\" (Wissenschaftliche Buchgesellschaft Darmstadt)."
 },
 "178": {
  "title_en": "Teaching activity; Theodor Schlatter to Bethel",
  "text_en": "Schlatter's academic teaching activity continues\nwith lectures on the Johannes- and\nMatthäusevangelium as well as seminars on the\nJakobusbrief and \"Die besondere Quelle des\nLukas\".\n\nHis son, Theodor Schlatter, is released by the\nWürttemberg church leadership to take up a\nlectureship at the Theologische Hochschule\nBethel (until January 1934).\nHis roughly 350 letters from Bethel to his\nfather are of importance for understanding and assessing\nAdolf Schlatter's work in the following\ndecade: Inventory no. 430/2"
 },
 "179": {
  "title_en": "Publications and lectures",
  "text_en": "\"Erlebtes. Erzählt von Adolf Schlatter\",\nFurche-Verlag Berlin 1924.\nThe lively demand for this autobiographical work required 2 further editions in the\nsame year, followed in 1925\nby the 4th edition, and in 1929 by an enlarged 5th edition. In German and Swiss church papers, but also in\ntheological specialist literature, the\nwork attracted widespread attention with a total of 74 reviews.\n\nThe Calwer Verlag publishes the 4th, completely revised edition of the Calwer\nBibellexikon, edited by D. Th.\nHermann. Among the twenty-one contributors Schlatter is represented with about 80 articles on biblical studies, the New Testament and New Testament\ncontemporary history.\n\nThe article \"Paulus\" is included in 1959 by Karl\nHeinrich Rengstorf in \"Das Paulusbild in\nder neueren deutschen Forschung\", Wissenschaftliche Buchgesellschaft Darmstadt.\n\nWith the lecture \"Wort und Schrift\" at the\nTheologische Woche in Bethel and a\nBible study on Römer 6 - 8 at the\n8. Tagung Christlicher Akademiker Württembergs, Schlatter remains faithful to these important\nbiennial meetings."
 },
 "180": {
  "title_en": "Enquiry about Christian-social groups; loan for Monbachtal",
  "text_en": "Encouraged by Schlatter's remark about Stöcker in 'Erlebtes', Arthur Staegle, Botnang, asks him, with reference to the appeal by D. Samuel Jäger for the founding of Christian-social conviction groups (in the 'Aufwärts' of 13 March 1924), to collaborate in the Württemberg group (Inventory no. 169/1). Jäger's appeal is connected with efforts in Westphalia and Württemberg to reconstitute an independent Christlich-soziale Volkspartei for the Reichstag election on 4 May 1924. Its deputies had joined the Deutschnationale Volkspartei since 1918. The break from the latter did not come about, however, because Jäger can make no resources available for political work and the leading Berlin representatives, especially the former Reich Chancellor Michaelis, want to remain with the Deutschnationale. Herein lies the reason for Schlatter's provisional reticence.\n\nThe Christliche Verein für Jugendwohlfahrt e.V. receives from Schlatter an interest-free loan for the development of the Tagungsstätte Monbachtal near Liebenzell."
 },
 "181": {
  "title_en": "Lectures: Galater- and Philipperbrief; seminar on the Hebräerbrief",
  "text_en": "For the first time since Bern and Greifswald Schlatter again lectures on the Galaterbrief; for the first time ever on the Philipperbrief. In the New Testament seminar he deals with the Hebräerbrief."
 },
 "182": {
  "title_en": "Publications 1926: Geschichte der ersten Christenheit; Gesammelte Arbeiten zur Schriftfrage",
  "text_en": "Like the \"Geschichte Israels\", so too\nSchlatter's \"Die Geschichte der ersten Christenheit\", issue II of the \"Beiträge\", 2nd series,\nwith 2 editions each in 1925 and 1927, met with considerable\nresonance (20 reviews). The book was reprinted in 1971\nby the Calwer Verlag; already in 1955\nit had appeared in London under the title The Church\nin the New Testament period in an English\ntranslation.\n\nWith the 1st edition of \"Hilfe in Bibelnot\"\nthe Treuzeiten-Verlag Velbert begins\nto bring out Schlatter's \"Gesammelte Arbeiten zur Schriftfrage\". In 1927 a\nsupplementary volume appears, in 1928 a collected volume with 28\nessays. The volume, widely read by pastors and laypeople and also reviewed in the specialist literature, appears after his death in\na 2nd and in 1953 in a 3rd enlarged edition\n(now: Treuzeiten-Verlag Gladbeck)."
 },
 "183": {
  "title_en": "Summer semester: lecture and publication note",
  "text_en": "For a last time he gives a lecture on the Johannesevangelium; in the seminar he deals once again (otherwise only in 1913) with the 1. Petrusbrief.\n\nThe \"Geschichte Israels von Alexander dem Großen bis Hadrian\", appearing in a 3rd, revised edition at the Calwer Verlag, and its later reprints in 1971 (Calwer Verlag), 1972 and 1977 (Wissenschaftliche Buchgesellschaft Darmstadt) show the enduring interest in this work."
 },
 "184": {
  "title_en": "Teaching in the summer semester",
  "text_en": "Schlatter lectures for the last time on \"Theologie des\nNeuen Testaments\" and deals in the seminar\nwith the history of the Römerbrief in the church."
 },
 "185": {
  "title_en": "Minor publications and lecture",
  "text_en": "A series of minor publications of lectures and biblical reflections reveals Schlatter's continuing service in Christian circles, especially the DCSV. Noteworthy is a lecture on \"Jesu Seelsorge\" in Sebastianweiler at the retreat of the Württ. Verband der Evang. Wohlfahrtspflegerinnen."
 },
 "186": {
  "title_en": "Ecumenism and autobiographical contribution",
  "text_en": "Schlatter knew himself bound, beyond the\nopposition of \"liberal\" and \"positive\", in a common\nregard for the ecumenical movement.\n\nLittle noticed is Schlatter's theologically\nsignificant autobiographical contribution\n\"Die mir gegebenen Ziele\" in the book \"Die Religionswissenschaft der Gegenwart in Selbstdarstellungen\", edited by Erich\nStange and published by Felix Meiner-Verlag Leipzig 1925."
 },
 "187": {
  "title_en": "Lectures and publications in Bethel",
  "text_en": "Significant are his lectures\n\"Das Gott wohlgefällige Opfer\" at the\nTheologische Woche in Bethel (Verlagshandlung Bethel 1926), later revised under the\ntitle \"Opfer - ein Verzicht?\" by Robert\nFrick (MBK-Verlag Bad Salzuflen\n1958). The participation of Karl Barth planned\nfor this week did not come about because of his\ncancellation. 3 letters from Barth to\nSchlatter, Inventory no. 425.\n\nTheodor Schlatter prints in issue 18 of the\nBethel \"Blicke aus Gottes Haus in\nGottes Welt\" 2 essays by his father:\n1. Der Idealismus und die Erweckungsbewegung. 2. Wittigs Leben Jesu.\nManuscript of a larger work \"Der\nIdealismus und die Erweckungsbewegung in\nmeiner Jugend\", 115 sheets: Inventory no. 769.857"
 },
 "188": {
  "title_en": "Contribution to \"Grundfragen einer Einigung der Kirche Christi\"",
  "text_en": "For the work \"Grundfragen einer Einigung der Kirche Christi\", dedicated \"to the convener of the Allgemeine Konferenz der Kirche Christi für Praktisches Christentum, Erzbischof Nathan Söderblom\", published by Christian Kaiser-Verlag München, Schlatter writes the introductory contribution \"Die letzte Bitte Jesu. Johannesevangelium 17, 20-25.\" Among the further seven contributions by German theologians is the study \"über den sogenannten 'Consensus quinque-säcularis' als Grundlage der 'Wiedervereinigung der Kirchen'\" by Adolf von Harnack, with which"
 },
 "189": {
  "title_en": "Relationship with Gerhard Kittel",
  "text_en": "After the surprisingly early death (1925) of his successor Professor Heitmüller, a theologically and personally good relationship developed with the latter's successor Gerhard Kittel, which will make the gradual reduction of his teaching activity easier for him."
 },
 "190": {
  "title_en": "Lecture in Freudenstadt",
  "text_en": "Schlatter's lecture at the 9. Tagung christlicher Akademiker in Freudenstadt, \"Der Anteil der Christenheit an der Gestaltung\nunseres Volkstums\", reveals for the first time his engagement with the aims of the\nChristian-social conviction groups."
 },
 "191": {
  "title_en": "Christlicher Volksdienst – weekly newspaper",
  "text_en": "Among the Christian-Socials in Germany, who consolidated in 1925/1926, the Württemberg group together with the Baden group began to take the lead. Wilhelm Simpfendörfer, a grammar-school teacher in Kornthal, publishes a weekly newspaper with the help of the office set up by Paul Bausch in Kornthal: \"Christlicher Volksdienst. Evang. Soziales Wochenblatt Süddeutschlands.\""
 },
 "192": {
  "title_en": "Publication no. 1 of the Christlicher Volksdienst",
  "text_en": "At the same time appears publication no. 1 of the Christlicher Volksdienst. It begins with Schlatter's essay \"Die Verpflichtung der Christenheit zum Dienst am Volk\", followed by his friend's essay, abridged, under the title \"Nationalismus und Christentum\". Inventory no. 627"
 },
 "193": {
  "title_en": "Seminar: Jakobusbrief",
  "text_en": "Schlatter deals in the New Testament seminar with the Jakobusbrief."
 },
 "194": {
  "title_en": "Lecture at the mission course in Bonn",
  "text_en": "He speaks at the 2. wissenschaftlicher\nMissionskurs in Bonn on 'Das Werden der\nKirche in der Urchristenheit',"
 },
 "195": {
  "title_en": "Lectures: Römerbrief and Matthäusevangelium",
  "text_en": "But he still carries on: he lectures on the Römerbrief, then on the Matthäusevangelium, both, admittedly, for the last time."
 },
 "196": {
  "title_en": "75th birthday",
  "text_en": "The 75th birthday is the occasion for official tributes and personal letters from friends.\n\nEduard Ellwein dedicates to the honouree in \"Zwischen den Zeiten\", issue 5/1927, the essay \"Schlatters Kritik an Luthers Römerbriefvorlesung\". It is at the same time the last and most thorough of the 17 reviews of Schlatter's 1917 work on Luther's interpretation of the Römerbrief.\n\nRegarding the volume \"Andachten\", printed by Oskar Günther Verlag Dresden 1927 and appearing after his death at the Calwer Verlag in 1938 (2nd), 1957 (3rd) and, revised, 1967 (1st), the father could occasionally make the surprising judgement \"that he considered them his scientifically most mature work\" (Theodor Schlatter in \"Adolf Schlatter im Rückblick\", Bertelsmann 1952).\n\nConnected with his lectures on New Testament theology, held periodically until 1926, is the revision of \"Der Glaube im Neuen Testament\", Calwer Verlag 1st ed. 1927. After more than 20 reviews of the first 3 editions, Rudolf Bultmann too follows in 1929 with a positive appreciation, which he confirms in 1953 in his Theologie des Neuen Testaments, page 538 ff.: \"Even his book \"Der Glaube im Neuen Testament\" (1st 1885, 2nd 1927) can be regarded as a New Testament theology in nuce\".\n\nThe work is reprinted in 1963 by the Wissenschaftliche Buchgesellschaft Darmstadt with prefatory remarks by Leonhard Goppelt. A 6th edition follows at the Calwer Verlag in 1932 with an introduction by Peter Stuhlmacher.\n\nAmong his further activities in this\neventful year, Schlatter's\nservices at mission events stand out."
 },
 "197": {
  "title_en": "Lecture at the meeting of the Bund deutscher evang. Missionare",
  "text_en": "at the meeting of the Bund deutscher evang.\nMissionare in Stuttgart on 'Das Ziel\nder Mission: Der neue Mensch',"
 },
 "198": {
  "title_en": "Last lectures and seminar topics",
  "text_en": "Schlatter gives the last of his 12 lectures on \"Leben Jesu\" (partly \"Geschichte Jesu\"), which he gave (only) in his\nTübingen period. Detailed\nmanuscripts: Inventory no. 198\n\nIn the New Testament seminar he deals\nonce more with \"Die johanneische Frage\".\n\nAfter a longer pause since 1919, he gives the\nlast of his altogether 10 lectures\n(the first in Bern 1881) on the Korintherbriefe."
 },
 "199": {
  "title_en": "Lecture in the Tübinger DCSV circle",
  "text_en": "and in the Tübinger DCSV circle at the close\nof the Tübinger Missionswoche on 'Das Ziel\nder Geschichte'."
 },
 "200": {
  "title_en": "Christlicher Volksdienst in Württemberg; theses by Prälat Wurm",
  "text_en": "In Württemberg, fellowship circles, Protestant teachers, Christian academics and also pastors, among them Stadtpfarrer Martin Haug, Tübingen, and the leader of Synodalgruppe I, Pfarrer Reiff, Mitteltal, have joined the Christlicher Volksdienst.\n\nPrälat Wurm publishes theses in which\nhe warns against too close a connection between\nchurch and politics."
 },
 "201": {
  "title_en": "Schlatter's objection to Prälat Wurm (article)",
  "text_en": "With the article 'Offene und verbundene\nAugen? Zu den Leitsätzen von Prälat Wurm'\nSchlatter raises an objection to this in the journal 'Christlicher Volksdienst' 7/1928. The article appears as a leaflet\nwith the title: 'Warum Christlichen Volksdienst? Eine Antwort von Univ.Prof. D. A.\nSchlatter an Prälat Wurm.' In addition it is\nprinted in the first issue of 'Volksdienstliches Wochenblatt der Christlich-So-"
 },
 "202": {
  "title_en": "Entry 25 February",
  "text_en": "zialen Gesinnungsgemeinschaften Westfalens und der Hochbargebiete\", cf. Inventory no. 628"
 },
 "203": {
  "title_en": "Seminar exercises concluded",
  "text_en": "With the topic \"Gnosis und Christentum in\nder neutestamentlichen Zeit\", Schlatter\nconcludes his exercises in the New Testament\nseminar."
 },
 "204": {
  "title_en": "Lecture on the Pastoralbriefe",
  "text_en": "Lecture on the Pastoralbriefe (otherwise only once, in 1900, but more often in the seminar)."
 },
 "205": {
  "title_en": "Der Evangelist Matthäus appears",
  "text_en": "In the period from 1882 to 1927 Schlatter lectured eighteen times, mostly for five hours a week, on the Matthäusevangelium. Now, as the fruit of this continuous work and at the same time as the first of his New Testament commentaries, there appears at the Calwer Verlag \"Der Evangelist Matthäus. Seine Sprache, sein Ziel, seine Selbständigkeit\". The work went through 6 editions up to 1963, among them the 2nd (1933), still supplemented by himself with a subject index. The 1st edition received attention in 15 reviews. At the same time there appears in issue 1/1929 of the \"Beiträge\" the treatise \"Die Kirche des Matthäus\"."
 },
 "206": {
  "title_en": "Freizeiten-Verlag publications and Schönblick meeting",
  "text_en": "The Freizeiten-Verlag Velbert publishes as Freizeit-Buch Nr. 3 under the\ntitle \"Ich will ihn loben bis zum Tod\"\na selection of 45 sermons by Schlatter\non New Testament texts, further, as\nFreizeit-Blätter Nr. 1 \"Die Botschaft des\nPaulus. Eine Übersicht über den Römerbrief\",\nNr. 2 \"Unsere Abendmahlseiner\" and Nr. 4\n\"Die Gabe des Christus. Eine Auslegung der\nBergpredigt\" after a lecture at the\n10. Tagung Christlicher Akademiker on the\nSchönblick.\nOn these 4 publications cf. the reviews by H. Rendtorff in the Theologische Literaturzeitung 54/1929."
 },
 "207": {
  "title_en": "Lecture in Tübingen and collaboration in the CV",
  "text_en": "With the lecture \"Was fordert die Lage unseres Volkes von unserer evangelischen Christenheit?\" in Tübingen, Schlatter continues his collaboration in the Christlicher Volksdienst, which won three seats in the Württemberg state election of 1928. The lecture appears with a foreword by Martin Haus, then regional leader of the CV, at the publishing house of the CV Korntal-Stuttgart.\n\nIn the revision of the Christliche Ethik, Calwer Verlag 3rd ed. 1929, Schlatter's involvement in the political sphere finds its expression, especially in the section \"Über das Recht der natürlichen Gemeinschaft\", whose\n\nsubsections leave nothing to be desired in\nclarity: Die Arbeit\nfür den Staat; Der Anteil an der Regierung;\nDie Teilnahme an der Rechtspflege; Die Gemeinschaft der Völker; Die Christenheit\nals politischer Verband.\n\nCompared with his New Testament\nwork, this ethical approach, still topical\ntoday, finds less attention; the\n18 reviews of the 1st (1914) and 2nd (1924)\nedition are followed by only 1 review each in Germany\n(1930 Werner de Boor in the Zeitschrift\nfür Theologie und Kirche) and the U.S.A.\n1931 in the Theological Magazine, Wartburg\nPublishing House, Chicago.\n\nThe later 4th edition of 1961 fares hardly\nbetter, with 2 reviews in specialist theology;\nof a further 3, the interest of the\nDeutsches Ärzteblatt in 1964 is noteworthy.\n\nThe broad range of his lecture themes is\nreflected in the collections of the Dreibücher of the Velbert-Verlag: Nr. 4/1929 \"Gesunde Lehre\" and Nr. 5/1929 \"Der Einzige und\nwir anderen\".\n\nSchlatter the pastoral counsellor is shown by the\nspecial prints \"Aus meiner Sprechstunde\", appearing since\n1925 at the Bethel-Verlag. A summary in 1929 is followed by the summary expanded to 32 topics in 1933 and, for the\n100th birthday, in 1952.\n\nMuch noticed too is his lecture at the\nTübinger Tagung der Südwestdeutschen Konferenz für Innere Mission, printed at the Quell-Verlag Stuttgart 1929."
 },
 "208": {
  "title_en": "Last New Testament lecture: Lukasevangelium",
  "text_en": "The last New Testament lecture: the Lukasevangelium. In general Schlatter, in his lectures on Matthäus, treated the synoptics Markus and Lukas alongside, but lectured separately on Lukas a few times."
 },
 "209": {
  "title_en": "Conclusion of academic teaching activity",
  "text_en": "Schlatter concludes his academic teaching activity, which he exercised for 99 semesters, with a lecture on \"Die religiöse Geschichte der Judenschaft von Alexander dem Großen bis Hadrian\", the theme of his book of 1901, on which he worked throughout his life in manifold ways.\n\nEven in the years since his retirement his lectures were well attended; it happened that he filled the university's ceremonial hall, which holds over 700 seats."
 },
 "210": {
  "title_en": "Theses of the Christlich-Sozialer Volksdienst",
  "text_en": "Whether Schlatter was directly involved in the theses of the Christlich-Sozialer Volksdienst (the result of the negotiations between the Christlicher Volksdienst and the Christlich-soziale Reichsvereinigung at the end of 1929 with the aim of participating in the Reichstag election on 14 September 1930, printed in issue no. 5 of the Christlicher Volksdienst, Konstanz 1930) cannot be demonstrated. The aim of the theses and of the appeal attached to them coincides, however, largely with his attitude. On his collaboration in the Christlicher Volksdienst as a whole, see also Paul Bausch,\n\nLebenserinnerungen und Erkenntnisse eines\nschwäbischen Abgeordneten\", self-published,\nKorntal 2nd ed. 1969 with remarks about\nSchlatter on pages 80, 86, 106, 289 as well as Karl\nHeim, Martin Haug and Theodor Haug: Inventory no. 503"
 },
 "211": {
  "title_en": "Lectures in Sebastiansweiler",
  "text_en": "Schlatter's concern to make the gospel\neffective in public life is also attested by\nhis lectures \"Das\nGesetz und das Evangelium in der Schule\"\nat a pedagogical-theological course period for female teachers in Sebastiansweiler,"
 },
 "212": {
  "title_en": "Study conference \"Wir Christen und die Juden\" in Stuttgart",
  "text_en": "\"Wir Christen und die Juden\" at the\n5. Studientagung zur Judenfrage in Stuttgart.\n\nBesides 16 lectures on the Johannesevangelium, Schlatter also held several seminars on the johanneische Frage.\nBeyond the commentary \"Der Evangelist Johannes: 'Wie er\nspricht, denkt und glaubt'\", now appearing at the Calwer Verlag, extensive\ncollections show his intensive\nwork on the entire field of the Corpus\nJohanneum: Inventory no. 317 - 323. Together\nwith 1948 the commentary receives 13 reviews; two further editions follow in 1960 and\n1975."
 },
 "213": {
  "title_en": "Farewell sermon in the Tübinger Stiftskirche",
  "text_en": "After more than 30 years of activity as an early preacher in the Tübinger Stiftskirche,\nSchlatter gives his farewell sermon on\nMatthäus 16, 24-28: \"Gehorsam ist besser\nals Leben\"."
 },
 "214": {
  "title_en": "Leadership of the Ortsgruppe Bethel taken over",
  "text_en": "Theodor Schlatter informs his father that he has taken over the leadership of the Ortsgruppe Bethel of the Christlich-sozialer Volksdienst. He keeps it until the dissolution of the Christlich-soziale Volkspartei in 1933.\n\nIn the following period he is also temporarily active supra-regionally, so that he is asked to take over the leadership of the Volksdienst 'Westfalen Ost'. He declines and restricts himself again to the Bethel area."
 },
 "215": {
  "title_en": "Publications and preliminary work",
  "text_en": "A further commentary appears: 'Das Evangelium des Lukas. Aus seinen Quellen erklärt.' Several collected volumes in his literary estate document his preliminary work: Inventory no. 315, 316\n\nSchlatter's students recount that he knew the Greek New Testament by heart, at any rate quoting it freely throughout his lectures. Now, in 1931, he brings out 'Das Neue Testament, übersetzt' with the Calwer Verlag. Among his almost immeasurable preliminary studies, 7 collected volumes from his estate stand out: 'Wörterbuch zum Griechischen NT', Inventory no. 399"
 },
 "216": {
  "title_en": "Theodor Schlatter: head of the Theologische Schule Bethel",
  "text_en": "Theodor Schlatter informs his father\nthat he has become head of the Theologische Schule\nBethel."
 },
 "217": {
  "title_en": "Theologische Woche in Bethel; essay on Bodelschwingh",
  "text_en": "As before, he takes part in the Theologische Woche in Bethel and in this connection writes 'Ein dankbares Wort zum 100. Geburtstag von Pastor Friedrich von Bodelschwingh'. This short essay also has an autobiographical character at the same time. Manuscript: Inventory no. 156, 661\n\nHe is still there for the theology students and the Christian academics:\n\"Erfolg und Mißerfolg im theologischen\nStudium. Eine Rede an die evangelischtheologische Fachschaft in Tübingen im\nJahr 1931\" as well as\n\"Drei Erzählungen Jesu\", Bible studies on\ntexts from the Lukasevangelium with discussions at the 14. Württ. Akademikertagung."
 },
 "218": {
  "title_en": "Debate with Karl Heim",
  "text_en": "His debate with Karl\nHeim, published in the Monatsschrift für Pastoraltheologie 1931/1932, causes a considerable stir; it was sparked by Schlatter's article\n\"Idealismus oder Theologie\", prompted by\nKarl Heim's \"Denken und Glauben\"."
 },
 "219": {
  "title_en": "Lecture \"Christ und Politik\" and pamphlets",
  "text_en": "For the last time Schlatter serves the Christlicher\nVolksdienst with the lecture \"Christ und Politik\" at its Theologische Arbeitsgemeinschaft in the Hans Sachs-Haus Stuttgart. He permits the distribution of the lecture in a\npamphlet. In a further pamphlet directly\nconcerning the Reich presidential elections in March/April\n1932, \"Was ist Wahrheit? Eine Untersuchung\ndes weltanschaulichen Wahrheitsgehalts und\ndes politischen Tatsachengehalts der Hitlerbewegung vom christlichen, nationalen und\nsozialen Standpunkt aus betrachtet\", the\nChristlich-soziale Volksdienst exercises sharp\ncriticism of National Socialism and sets out\nthe position of its representatives in the state parliaments and in the Reichstag (14)."
 },
 "220": {
  "title_en": "Lecture: God's rule and worldly power in the NT",
  "text_en": "\"Gottes Herrschaft und weltliche Macht im Neuen Testament\" (Theologische Woche Bethel);"
 },
 "221": {
  "title_en": "Lecture: Menschengemeinschaft - Gottesgemeinschaft",
  "text_en": "\"Menschengemeinschaft - Gottesgemeinschaft\" (16. Freudenstädter Tagung);\n\nthose who read only the title, however, brand\nSchlatter even back then as a sympathiser of the \"Deutsche Christen\"."
 },
 "222": {
  "title_en": "Themes and writings (1933)",
  "text_en": "The themes of several lectures and treatises printed in 1933, some already delivered or written in the autumn of 1932, reveal Schlatter's struggle to come to terms with the dawn of the \"3. Reich\" and the challenge it posed to the church:"
 },
 "223": {
  "title_en": "Letters and publications",
  "text_en": "Theodor Schlatter reports to his father that, to counter the growing National Socialist agitation, he has published a pamphlet of the Christlich-sozialer Volksdienst. His letters from 1930 - 1933 show that the continuation of the Theologische Schule was repeatedly called into question, and, thanks in part to his close ties with Bodelschwingh, they contain many details about the ecclesiastical and political situation, which he discusses with his father.\n\nAnother commentary appears: \"Der Brief des Jakobus, ausgelegt.\" Among the manuscripts on James, one volume shows Schlatter's meticulousness particularly clearly: \"Der Wortschatz des Jakobus; Silbenzählung zum Jakobusbrief.\" Inventory no. 347\n\nA considerably greater response than the commentary on the Epistle of James, so prized by Schlatter the ethicist, is provoked by \"Die Theologie des Judentums nach dem Bericht des Josephus\" (\"Beiträge\", 2. Reihe, Band 25), with 24 reviews, including some in German and foreign theological journals, also in the Orientalische Literaturzeitung (H. Dielius) and in The Jewish quarterly review London (Cohen). What he composes here over 270 pages, the fruit of years of work, which found expression in a wealth of studies and collections extending as far as a \"Lexikon des Josephus\", Inventory no. 370-333. 398-408."
 },
 "224": {
  "title_en": "Bodelschwingh elected Reich Bishop",
  "text_en": "Friedrich von Bodelschwingh, Schlatter's godson, is elected Reich Bishop amid difficulties."
 },
 "225": {
  "title_en": "Repetent Fritz Weigel tries to win Schlatter over",
  "text_en": "Repetent Fritz Weigel of the Seminar Blaubeuren, who is on the side of the 'Deutsche Christen', tries once more to win Schlatter over. 'Last August (1932) we spoke in Boll about Volksdienst and NSDAP, and you did not share my forward-pressing stance.'"
 },
 "226": {
  "title_en": "Bodelschwingh resigns",
  "text_en": "A few weeks later he finds himself compelled to resign again."
 },
 "227": {
  "title_en": "Letter to the man who had resigned",
  "text_en": "A letter to the man who had resigned is significant for assessing Schlatter's deeper view of the events of the time."
 },
 "228": {
  "title_en": "Honorary doctorate Berlin",
  "text_en": "In turn, Schlatter is honoured by the Philosophische Fakultät Berlin with the Doktor phil.\nh.c. The tribute closes\nwith the sentence: \"Die Fakultät ehrt in Professor\nvon Schlatter den Vertreter und Erhalter\neiner Philologia sacra im guten alten Sinne,\ndie sich von der genauen und getreuen Auffassung des Sprachlichen und Geschichtlichen\nzu einer lebensvollen und Leben weckenden\nGesamtsansicht der neutestamentlichen Überlieferung erhebt.\" Inventory no. 832"
 },
 "229": {
  "title_en": "80th birthday and honours",
  "text_en": "For his 80th birthday the celebrant receives\nan abundance of grateful congratulatory letters\nfrom all over Germany and Switzerland. The\nseries of representative good wishes from\nstate, church and university is headed by\nReichspräsident von Hindenburg and the\nWürttemberg Staatspräsident Dr. Dehlinger; among them is also the Bürgerrat of St. Gallen. Inventory no. 167, 832, 853.\n\nThe conferral of the Halsschild des Deutschen Reiches, applied for by the Evang.-Theologische Fakultät\nTübingen for Adolf von Schlatter (and Karl\nMüller) and hitherto awarded among theology professors only to Adolf von\nHarnack, is not granted by Berlin. Inventory no. 830"
 },
 "230": {
  "title_en": "Theological theses and the \"Betheler Bekenntnis\"",
  "text_en": "Bodelschwingh sends to a number of\ntheology professors, among them Adolf Schlatter\nand Karl Barth, a series of detailed theological theses intended to serve as a basis for the\ndebate with the \"Deutsche Christen\". The principal authors\nare Dietrich Bonhoeffer and Hermann Sasse.\nFurther collaborators are Georg Merz and Wilhelm Vischer, the latter on the Jewish question. Secretary of the undertaking is Gerhard Stratenwerth. Schlatter is, as later regarding Barmen, sceptical of the idea\nof a theological confrontation through a\nnew confessional formulation. He also comments carefully on\nthe draft. Of all those consulted, Schlatter and Barth\nexpressed themselves at the greatest length.\n\n\"Betheler\" Bekenntnis\", booklet \"Professor\nSchlatter\", with his handwritten remarks, together with correspondence with Bodelschwingh and Stratenwerth. Inventory 695\n\nDetailed account of the whole matter with background information in Bethge's Bonhoeffer biography, 3 1969 Chr. Kaiser-Verlag München."
 },
 "231": {
  "title_en": "Article in the Tübinger Chronik",
  "text_en": "On this matter, an article on the front page of the\nTübinger Chronik. Inventory no. 853"
 },
 "232": {
  "title_en": "Freudenstadt conference (Bible studies)",
  "text_en": "At the 15. Freudenstädter Tagung for Christian academics from Württemberg and Baden and the 41. Allgemeine Christliche Studententagung in Bad Boll with the general secretary of the DCSV, Eberhard Müller, Berlin, Schlatter's Bible studies with discussion are once again an enlivening and deepening element."
 },
 "233": {
  "title_en": "Discussions and lecture at the friends' conference",
  "text_en": "The thorough discussions in the context of the very well-attended 16. Freundestagung (Christian academics' conference for Württemberg and Baden) are conducted openly and fraternally, partly with the participation of clear adherents of the Glaubensbewegung Deutscher Christen. In the discussion, especially after his lecture 'Menschengemeinschaft - Gottesgemeinschaft', Schlatter agrees with the view that the present völkisch awakening holds opportunities for the church's proclamation, which is thereby called to a mission among the people. First, however, he clearly draws a boundary: 'The inability to grasp that the church is something other than a national organisation, - the pastor in the brown shirt, who ... derives his authority no longer from the church but from the state,' - these are symptoms that compel struggle.' 'To the race-conscious Teuton one must say: 'God's hand will find you yet,' to the reviled Jew: 'Whatever your descent may be, you live\n\nby God's grace like the Teuton with his blond hair; come to us, Christ is calling; come to us, we celebrate the Lord's Supper; come to us, have your child baptised, brother in the Lord'!\nPrinted minutes by Dr. Oehler, Schorndorf: Inventory no. 126\n\nIn the commemorative volume \"Viele Saaten - Eine Ernte\" for the centenary of the Calwer Verlagsverein 1833-1933, Schlatter writes in his contribution \"Autor und Verlag\": \"... for my life's work it has acquired inestimable significance that I entered into a firm relationship with the Calwer Verlag.\"\nHis contribution (pages 79 - 90) is a piece of autobiography; the best proof that his \"working partnership\" with the publishing house was, as he writes, \"unique\"."
 },
 "234": {
  "title_en": "Allgemeine Christliche Studententagung Bad Boll",
  "text_en": "At the 15. Freudenstädter Tagung for Christian academics from Württemberg and Baden and the 41. Allgemeine Christliche Studententagung in Bad Boll with the general secretary of the DCSV, Eberhard Müller, Berlin, Schlatter's Bible studies with discussion are once again an enlivening and deepening element."
 },
 "235": {
  "title_en": "Commentary \"Paulus, der Bote Jesu\"",
  "text_en": "The next commentary: \"Paulus, der Bote Jesu. Eine Deutung seiner Briefe an die Korinther.\"\nSchlatter also gave ten lectures on the Corinthian epistles, and in his literary estate there are 5 volumes of studies and collections on them. Inventory no. 329, 330.\nThe response in theology and church, with 8 reviews, is modest, yet the demand nevertheless gave rise to 3 further editions in 1956, 1962 and 1969."
 },
 "236": {
  "title_en": "Letters around the Barmen Declaration",
  "text_en": "Schlatter's letters before the Barmen Declaration\nto Pfarrer Karl Dürr (Baden) and\nto Pastor von Bodelschwingh (Bethel)\nas well as, above all, after the Barmen Declaration\nof 31 May 1934\nto Pfarrer Wolfgang Metzger (Württemberg)\nreveal that he - similarly to 1933\nwith the draft of the \"Betheler Bekenntnis\" - does not consider it appropriate to the church's commission to meet the challenges of the time with new confessional formulation."
 },
 "237": {
  "title_en": "Letters around the Barmen Declaration",
  "text_en": "Schlatter's letters before the Barmen Declaration\nto Pfarrer Karl Dürr (Baden) and\nto Pastor von Bodelschwingh (Bethel)\nas well as, above all, after the Barmen Declaration\nof 31 May 1934\nto Pfarrer Wolfgang Metzger (Württemberg)\nreveal that he - similarly to 1933\nwith the draft of the \"Betheler Bekenntnis\" - does not consider it appropriate to the church's commission to meet the challenges of the time with new confessional formulation."
 },
 "238": {
  "title_en": "Publications and addresses",
  "text_en": "At the same time he struggles in his own way for clarity:\n\"Das Alte Testament und der Talmud\", a contribution to \"Das Alte Testament als Buch der\nKirche\", issue 7/1934 of \"Bekennende Kirche\",\nChristian Kaiser-Verlag, München (August 1934);\n\"Der Kampf des Paulus gegen die Gleichmachung\", address before the Evang.-Theologische\nFakultät Tübingen;\n\"Das Evangelium und das Bekenntnis\", address to\na student circle."
 },
 "239": {
  "title_en": "Telegram of the university teachers",
  "text_en": "About 120 German Protestant theological\nuniversity teachers call on Reich Bishop Ludwig\nMüller by telegram to resign.\nSchlatter's name also appears on the telegram of the professors of the Evang.-Theologische Fakultät Tübingen. Inventory no. 320"
 },
 "240": {
  "title_en": "Letter of refusal from the Reich Bishop",
  "text_en": "The hectographed letter of refusal from the\nReich Bishop to Schlatter bears the stamp \"Deutsche Evangelische Kirche\" with\nLuther rose and swastika. Inventory no.\n159/3"
 },
 "241": {
  "title_en": "1935: Commentaries and lectures",
  "text_en": "The next commentary: \"Markus, der Evangelist für die Griechen.\"\n\nHere too there is more work behind it than the absence of separate lectures by Schlatter on the Gospel of Mark might suggest: 3 volumes of exegetical collections on Mark, Inventory no. 314\n\nOf greater impact than the Mark commentary, which is not reprinted, is the commentary on the Epistle to the Romans appearing in the same year under the title: \"Gottes Gerechtigkeit\".\n\nEver since his lectures to men in Bern, Schlatter had occupied himself intensively with the Epistle to the Romans and, between 1884 and 1927, gave sixteen lecture courses on it. In his literary estate there are 5 volumes of studies and collections on the Epistle to the Romans, Inventory no. 326-328\n\n4 further editions up to 1975 attest to the considerable impact of the commentary; whether the theologically significant interpretation of \"Gottes Gerechtigkeit\" in Romans 1, 16, which corrects Luther, was truly able to prevail remains open.\n\nAmong various lectures and Bible studies, Schlatter's lecture at a women students' retreat \"Was sagt das Neue Testament der Frau\" stands out, which went through 3 editions in the study series of the Burckhardthaus, and\n\nhis Bible study \"Das Unser Vater\", which\nwas printed by the DCSV in its bulletins in 1935\nand later appeared with the Furche-Verlag Berlin in 1938."
 },
 "242": {
  "title_en": "Enquiry from Reich Youth Pastor Zahn",
  "text_en": "Reich Youth Pastor Zahn asks Schlatter (to whom he is related through Theodor Zahn)\nfor permission to reprint\nparts of \"Erlebtes\" in the youth newspaper \"Das\nWort\",\nas well as for an article in this newspaper\nintended to help overcome the reluctance of confirmands and young people to take part in the Lord's Supper.\n\nZahn encloses with his letter, \"strictly confidential\",\nthe \"Denkschrift des Reichsjugendpfarrers\nvom 25. Juli 1934\" on the \"Spannungen zwischen Evangelischer Kirche und Hitlerjugend\"\n- a harrowing document about the\nconsequences of the incorporation of the Protestant youth into\nthe Hitler Youth, carried out from the end of 1933 and finally through the\nchurch law of 2 May 1934. Inventory no. 169/5"
 },
 "243": {
  "title_en": "Christmas tract \"Wird der Jude über uns siegen?\" and confiscation",
  "text_en": "Schlatter's word for the Christmas season \"Wird\nder Jude über uns siegen?\", Freizeit-Blätter\nNr. 8, Velbert 1935, with a 2nd edition in 1936, achieves, on account of its provocative and misleading title, a circulation of 40,000 copies, also in party circles, but is\nconfiscated and withdrawn by decree of the Preußische Geheime Staatspolizei\nof 13 May 1936, in agreement with the\nReich Minister for Church Affairs. Inventory no. 169/6\n\nEven zealous Confessing Christians, insofar as they confined themselves to reading the provocative title, felt\nconfirmed in that absurd judgement of Schlatter\nas a \"grandfather of the Deutsche Christen\", which persists to this day among some theologians."
 },
 "244": {
  "title_en": "Commentary: Die Kirche der Griechen",
  "text_en": "Another commentary: \"Die Kirche der\nGriechen im Urteil des Paulus. Eine Auslegung seiner Briefe an Timotheus und Titus.\"\n\nAmong the 12 journals with reviews,\nthe Monatsschrift Gottesdienst und kirchliche Kunst Göttingen (Kunze), absent for the other commentaries, is notable; in 1958 a\n2nd edition follows.\n\nDespite few lectures and seminars, there are\n2 volumes of exegetical collections in his estate\n\"zu 1. und 2. Tim. und Titus\", together with one\nvolume each of \"Wörter Past\", \"Philemon\" and \"Pastoraltheologie\" (shorthand). Inventory no. 336-339"
 },
 "245": {
  "title_en": "February: Flammenzeichen article",
  "text_en": "In issue 5 of the \"Flammenzeichen\" an\nugly article appears about Schlatter as the author of \"Wird der Jude über uns siegen?\".\nInventory no. 833\n\nHis slowly waning physical strength no longer allows \"the old man\", as he is called in the Tübingen circle of lecturers and among the Christian academics, to take part in the newly established academics' conference. His exposition of the last three parables of Jesus (Matthew 24, 45 - 25, 30), prepared for it, appears as issue 2 of \"Kirche im Aufbau\",\nStauda-Verlag Kassel 1936 under the title\n\"Die Kirche wie Jesus sie sah\".\n\nThis vision also corresponds to the writing\n\"Müssen wir heute lutherisch oder reformiert sein?\", with which the Freizeiten-Verlag in 1936 publishes the earlier lectures \"Die\nGrenzen der kirchlichen Gemeinschaft\" and\n\"Das Evangelium und das Bekenntnis\", together with further contributions by Wilhelm\nLütgert and Hermann Strathmann \"zur Frage\neiner neuen kirchlichen Einheit\"."
 },
 "246": {
  "title_en": "Contribution \"Theologie, Konfession und Glaube\"",
  "text_en": "The contribution \"Theologie, Konfession und\nGlaube. Sechs mir gestellte Fragen und\nmeine Antwort\" also belongs in this\ncontext. Compare on this also Schlatter's attitude towards the Theologische Erklärung von\nBarmen 1934. Proven, at least, in the confessional struggle, it is nonetheless for him no sufficient\nbasis for \"die Kirche, wie Jesus sie sah\".\n\nFor the annual \"Gottesjahr\" (1936), published by the Stauda-Verlag and edited by Wilhelm Stählin, Schlatter writes\nthe contribution \"Heilung\"."
 },
 "247": {
  "title_en": "Christmas meditation \"Marias Mutterglück\"",
  "text_en": "This year's Christmas meditation\n\"Marias Mutterglück\" is published by August de Haas\nas a brochure by the Stiftungsverlag Potsdam\n(1936, 21937).\n\nThree of these publications go back to a meeting of Schlatter with Wilhelm Stählin on the occasion of the Berneuchener Konferenz 1936 in Tübingen. Old Berneuchen members recount that he was the only Tübingen theology professor to offer lodging for it; Stählin was his guest. Superficial liturgical zeal was not in Schlatter's nature, but for the endeavour of the Berneuchen movement concerning the bodily reality of the Word, especially also in the Lord's Supper, he had full understanding, cf. among others \"Der vergrabene Schatz im christlichen Sakrament\" (Freizeiten-Verlag Velbert 1929) and \"Unsere Abendmahlsfeier\" (same publisher 1928)."
 },
 "248": {
  "title_en": "Last commentary and the book \"Kennen wir Jesus?\"",
  "text_en": "The last of the nine commentaries published since 1929 by the Calwer Verlag: \"Petrus und Paulus. Nach dem 1. Petrusbrief.\" \n\nAmong the corresponding 4 volumes in his estate is also the manuscript for this commentary: Inventory no. 348 \n\nThe work, significant for its inclusion of Paul, remains without discernible impact; it is confined to this single edition. \n\nBy contrast, the last book he published in his lifetime has a strong resonance: \"Kennen wir Jesus? Ein Gang durch ein Jahr im Gespräch mit ihm.\" Published by the Calwer Verlag in 1937 and 1938, it still records 12 reviews, including Otto Michel in the Theologische Literaturzeitung 1939.\n\nFor his 100th birthday, the 3rd edition appears in 1952\nwith the Freizeitverlag Gladbeck; with\na foreword by Hans Ströh\nthe Brunnenverlag Gießen brings out a\n4th edition in 1982.\n\nThe title expresses the question that Adolf\nSchlatter, including himself, put to all Christians, to the whole church and its theologians throughout his life and still\nputs today."
 },
 "249": {
  "title_en": "Address for Wilhelm Lütgert's birthday",
  "text_en": "For Wilhelm Lütgert's birthday he composes\nan \"Adresse\" with which he honours Lütgert's theological life's work. It\nis presented to Lütgert by Hermann Strathmann together with a\nblessed dedication from many friends on\n9 May 1937, and Lütgert's reply\nto the collective dedication is incorporated into his article\n\"Wilhelm Lütgert als Theologe\".\nAfter the death of both, there appeared in issue 1/1938\n(20 September 1938) of the \"Beiträge\": Adolf\nSchlatter und Wilhelm Lütgert zum Gedächtnis, together with Gerhard\nKittel's memorial address for Schlatter and the article \"Adolf\nSchlatters Gabe an die systematische Theologie\" by Paul Althaus. Inventory no. 39"
 },
 "250": {
  "title_en": "Declarations on decorations and descent",
  "text_en": "Schlatter has to submit declarations concerning his\npossession of decorations and honours, his\nnon-membership of a Freemason organisation and his Aryan descent.\n\nOnce more a short autobiographical\nword: \"Mein Studium: Der Theologieprofessor\"."
 },
 "251": {
  "title_en": "Involvement in the DCSV and a manuscript",
  "text_en": "Schlatter writes it for the bulletins\nof the DCSV, for which he had already been active in his\nBerlin period and which he then served further in\nTübingen, from 1908 continuously with\nword and writing, counsel and deed.\n\nAlongside numerous reports and testimonies\nby his students and friends about this manifold activity and his own remarks\nabout it in the \"Rückblick\" and in \"Beteläuten\",\nthere is also in his estate his manuscript (presumably\nwritten around 1920): \"Meine\nBegegnungen mit der CSV\", Inventory no. 152\n\nA lasting sign of this is the house\nof the Tübingen DCSV circle and the Württ. Altfreundeverband on the Österberg. Its\ntransfer to the Evang. Landeskirche as the\n\"Adolf-Schlatter-Haus der evang. Studentengemeinde\" in November 1938 he did not\nlive to see."
 },
 "252": {
  "title_en": "Study on the Epistle to the Hebrews and manuscripts",
  "text_en": "Ever since his lecture on the Epistle to the Hebrews in 1893 in\nBern, Schlatter had repeatedly occupied himself with the\nEpistle to the Hebrews. To it his\nlast study is devoted, on which his son noted:\n\"Letztes begonnenes Werk: Herbst 1937.\"\n\nManuscript: Inventory no. 345.\nManuscript \"Koller Hebr.\", 4-hour course, Bern\nSS 93\", Inventory: 340\nCollections on the conceptual group \"Heilig\" as well as\nexegetical collections: Inventory: 343-344"
 },
 "253": {
  "title_en": "Death of Wilhelm Lütgert",
  "text_en": "Schlatter's long-standing friend Professor Wilhelm Lütgert, since 1904 co-editor of the \"Beiträge\", dies in his 71st year."
 },
 "254": {
  "title_en": "Request to Paul Althaus to edit the \"Beiträge\"",
  "text_en": "Schlatter asks Professor Paul Althaus, Erlangen, to take over the editing of the \"Beiträge\"."
 },
 "255": {
  "title_en": "Death of Adolf Schlatter",
  "text_en": "Adolf Schlatter dies in his 86th year."
 },
 "256": {
  "title_en": "Burial in Tübingen",
  "text_en": "\"In the presence of a vast congregation of young and old, of students, pastors and professors and plain men and women of the people, he was buried on the morning of 23 May in the cemetery in Tübingen.\" So writes Samuel Oettli jr. in \"Professor D. Adolf Schlatter, 1852-1938\", H. Tschudi & Co., St. Gallen 1939, page 19.\nThe son, Prälat Theodor Schlatter, delivers the graveside address on Jesus' word in the farewell discourse, John 15, 8: \"Darin wird mein Vater geehrt, daß ihr viel Frucht bringet und werdet meine Jünger.\"\n\nfor the Evang. Kirchengemeinde Tübingen, Pastor\nvon Bodelschwingh for the Betheler Gemeinde and Stadtpfarrer Frohmayer\nfor the Calwer Verlag. Obituaries from the Evang.\nTheologische Fachschaft, the DCSV, the\nChristlicher Akademikerverband, the Tübinger Wingolf and the CVJM Tübingen\nfollow.\n\nAt the academic ceremony in the afternoon\nProfessor Gerhard Kittel, in his\nequally brilliant and moving memorial address,\ndraws the picture of a theologian who knew: 'Before\nour own forming ... stands the receiving, that\nprocess which we call seeing.'\n\nAt the gathering afterwards in the house of the DCSV, the picture of Adolf Schlatter\nis rounded out with many freely expressed thoughts and\nrecollections - a man who, as a\nscholarly theologian, was a teacher and preacher of the church, a pastor\nand counsellor of many students, laypeople and\nministers, a man of diakonia, mission and\necumenism, a friend of nature and servant\nto people and state, and in all this not least a 'critic of criticism': a\n'positive' theologian in the deepest sense of that\nword.\n\nErnst Bock"
 }
};
